-- The Houzs supply chain structure, as its own schema `scm`: 248 tables, 22 views, 1 materialized view,
-- 42 enums, 64 functions and 31 triggers, plus public.companies (the one table outside scm it points to).
-- Structure only, no rows. Generated on 2026-10-07 from read-only catalogue exports of the live Houzs
-- database, because Houzs's own repository cannot rebuild this schema (its scm-schema README). Three
-- dated backup tables (bak_*) were left out. Houzs's row-level policies for the `authenticated` role were
-- left out too: every table has row level security on with no policy, so only pos_app and the service
-- role can reach it. The rental side (schema pos) is untouched.
-- Five functions still name Houzs tables that do not exist here (public.mfg_product_category,
-- public.positions, public.projects, public.project_event_types): acc_register_item_group,
-- sync_user_to_tms, vp_build_payloads. They are created but will fail if called until that is decided.
-- REVERSAL: DROP SCHEMA scm CASCADE; DROP TABLE public.companies;
create schema scm;
create extension if not exists pg_trgm with schema extensions;
set local check_function_bodies = off;
set local search_path = public, extensions;

-- The one table outside scm that it points to: every scm row carries the company it belongs to.
create table public.companies (
  id bigint generated by default as identity primary key,
  code text not null unique,
  name text not null,
  is_active integer not null default 1,
  created_at timestamp with time zone not null default now()
);
alter table public.companies enable row level security;
grant all on public.companies to pos_app, service_role;
insert into public.companies (code, name) values ('CONTS', 'The Conts');

