CREATE OR REPLACE FUNCTION scm.acc_register_item_group(p_code text, p_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'public', 'pg_temp'
AS $function$
BEGIN
  -- The label becomes an enum member and a document-facing code: keep it in
  -- the same shape the nine originals have, and refuse anything else by name.
  IF p_code !~ '^[A-Z][A-Z0-9_]{1,29}$' THEN
    RAISE EXCEPTION 'group code % must be 2-30 chars of A-Z, 0-9, _ starting with a letter', p_code;
  END IF;
  IF coalesce(trim(p_name), '') = '' THEN
    RAISE EXCEPTION 'group name is required';
  END IF;

  -- BOTH enums carry the taxonomy (the scm schema is a full sibling of
  -- public); extending only one would let a product save in one schema and
  -- fail in the other.
  EXECUTE format('ALTER TYPE public.mfg_product_category ADD VALUE IF NOT EXISTS %L', p_code);
  EXECUTE format('ALTER TYPE scm.mfg_product_category ADD VALUE IF NOT EXISTS %L', p_code);

  INSERT INTO scm.acc_item_groups (code, name)
  VALUES (p_code, trim(p_name))
  ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, is_active = true, updated_at = now();
END;
$function$;

CREATE OR REPLACE FUNCTION scm.acc_rename_account(p_old text, p_new text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  n_accounts int; n_children int; n_jel int; n_pvc int; n_pvl int;
  n_vendor int; n_acq int; n_acq2 int; n_acq3 int;
  n_bankcfg int; n_stmts int; n_roles int;
BEGIN
  IF p_old IS NULL OR p_new IS NULL OR p_old = p_new THEN
    RAISE EXCEPTION 'rename needs two different codes';
  END IF;
  IF p_new !~ '^\d{3}-[A-Za-z0-9]{4}$' THEN
    RAISE EXCEPTION 'new code % is not in the NNN-XXXX account-code shape', p_new;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM scm.accounts WHERE account_code = p_old) THEN
    RAISE EXCEPTION 'account % does not exist in any company', p_old;
  END IF;
  IF EXISTS (SELECT 1 FROM scm.accounts WHERE account_code = p_new) THEN
    RAISE EXCEPTION 'account % already exists — renaming onto a live code would merge two books; refused', p_new;
  END IF;

  -- New rows first, so the composite FKs have somewhere to point the moment
  -- references start moving. created_at rides along: the account is the same
  -- account, only its number changed.
  INSERT INTO scm.accounts
    (company_id, account_code, account_name, account_type, parent_code,
     is_active, acc_money, special_type, created_at)
  SELECT company_id, p_new, account_name, account_type, parent_code,
         is_active, acc_money, special_type, created_at
  FROM scm.accounts WHERE account_code = p_old;
  GET DIAGNOSTICS n_accounts = ROW_COUNT;

  UPDATE scm.accounts SET parent_code = p_new WHERE parent_code = p_old;
  GET DIAGNOSTICS n_children = ROW_COUNT;

  UPDATE scm.journal_entry_lines SET account_code = p_new WHERE account_code = p_old;
  GET DIAGNOSTICS n_jel = ROW_COUNT;
  UPDATE scm.payment_vouchers SET credit_account_code = p_new WHERE credit_account_code = p_old;
  GET DIAGNOSTICS n_pvc = ROW_COUNT;
  UPDATE scm.payment_voucher_lines SET debit_account_code = p_new WHERE debit_account_code = p_old;
  GET DIAGNOSTICS n_pvl = ROW_COUNT;
  UPDATE scm.acc_vendor_memory SET debit_account_code = p_new WHERE debit_account_code = p_old;
  GET DIAGNOSTICS n_vendor = ROW_COUNT;
  UPDATE scm.acc_company_acquirers SET transit_account_code = p_new WHERE transit_account_code = p_old;
  GET DIAGNOSTICS n_acq = ROW_COUNT;
  UPDATE scm.acc_company_acquirers SET fee_account_code = p_new WHERE fee_account_code = p_old;
  GET DIAGNOSTICS n_acq2 = ROW_COUNT;
  UPDATE scm.acc_company_acquirers SET bank_account_code = p_new WHERE bank_account_code = p_old;
  GET DIAGNOSTICS n_acq3 = ROW_COUNT;
  UPDATE scm.acc_bank_statement_config SET account_code = p_new WHERE account_code = p_old;
  GET DIAGNOSTICS n_bankcfg = ROW_COUNT;
  UPDATE scm.acc_bank_statements SET account_code = p_new WHERE account_code = p_old;
  GET DIAGNOSTICS n_stmts = ROW_COUNT;
  UPDATE scm.acc_account_roles SET account_code = p_new WHERE account_code = p_old;
  GET DIAGNOSTICS n_roles = ROW_COUNT;

  -- Every reference has moved; RESTRICT has nothing left to protect.
  DELETE FROM scm.accounts WHERE account_code = p_old;

  RETURN jsonb_build_object(
    'accounts', n_accounts, 'children', n_children,
    'journal_lines', n_jel, 'pv_credit', n_pvc, 'pv_debit', n_pvl,
    'vendor_memory', n_vendor, 'acquirers', n_acq + n_acq2 + n_acq3,
    'bank_config', n_bankcfg, 'bank_statements', n_stmts, 'roles', n_roles);
END;
$function$;

CREATE OR REPLACE FUNCTION scm.apply_so_header_cas(p_doc_no text, p_expected_version integer, p_required_lease text, p_patch jsonb, p_recustomer boolean DEFAULT false, p_customer_name text DEFAULT NULL::text, p_customer_phone text DEFAULT NULL::text, p_customer_email text DEFAULT NULL::text, p_apply_warehouse boolean DEFAULT false, p_warehouse_id uuid DEFAULT NULL::uuid, p_apply_delivery_date boolean DEFAULT false, p_delivery_date date DEFAULT NULL::date, p_company_id bigint DEFAULT NULL::bigint, p_rebind_line_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(applied boolean, current_version integer, resolved_customer_id uuid, conflict_reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_row scm.mfg_sales_orders%ROWTYPE;
  v_saved_version integer;
  v_customer_id uuid;
  v_assignments text;
  v_sql text;
  v_unlinked boolean;
  v_frozen uuid[];
BEGIN
  SELECT * INTO v_row
  FROM mfg_sales_orders
  WHERE doc_no = p_doc_no
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, NULL::integer, NULL::uuid, 'not_found'::text;
    RETURN;
  END IF;
  IF v_row.version <> p_expected_version THEN
    RETURN QUERY SELECT false, v_row.version, NULL::uuid, 'version'::text;
    RETURN;
  END IF;
  IF p_required_lease IS NOT NULL THEN
    IF v_row.edit_lease_token IS DISTINCT FROM p_required_lease
       OR v_row.edit_lease_expires_at IS NULL
       OR v_row.edit_lease_expires_at <= now() THEN
      RETURN QUERY SELECT false, v_row.version, NULL::uuid, 'lease'::text;
      RETURN;
    END IF;
  ELSIF v_row.edit_lease_token IS NOT NULL
        AND v_row.edit_lease_expires_at IS NOT NULL
        AND v_row.edit_lease_expires_at > now() THEN
    RETURN QUERY SELECT false, v_row.version, NULL::uuid, 'lease'::text;
    RETURN;
  END IF;

  IF jsonb_typeof(p_patch) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Sales Order CAS patch must be a JSON object'
      USING ERRCODE = '22023';
  END IF;

  SELECT string_agg(
    format(
      '%1$I = CASE WHEN $1 ? %2$L THEN p.%1$I ELSE t.%1$I END',
      a.attname,
      a.attname
    ),
    ', ' ORDER BY a.attnum
  )
  INTO v_assignments
  FROM pg_attribute a
  WHERE a.attrelid = 'scm.mfg_sales_orders'::regclass
    AND a.attnum > 0
    AND NOT a.attisdropped
    AND a.attgenerated = ''
    AND a.attidentity = ''
    AND a.attname <> 'doc_no';

  v_sql := format(
    'UPDATE scm.mfg_sales_orders AS t '
    'SET %1$s '
    'FROM jsonb_populate_record(NULL::scm.mfg_sales_orders, $1) AS p '
    'WHERE t.doc_no = $2 AND t.version = $3 RETURNING t.version',
    v_assignments
  );
  EXECUTE v_sql INTO v_saved_version USING p_patch, p_doc_no, p_expected_version;
  IF v_saved_version IS NULL THEN
    RETURN QUERY SELECT false, v_row.version, NULL::uuid, 'version'::text;
    RETURN;
  END IF;

  IF p_recustomer
     AND NULLIF(btrim(p_customer_name), '') IS NOT NULL
     AND NULLIF(btrim(p_customer_phone), '') IS NOT NULL THEN
    v_customer_id := upsert_customer_by_name_phone(
      p_customer_name, p_customer_phone, p_customer_email, p_company_id
    );
    UPDATE mfg_sales_orders
    SET customer_id = v_customer_id
    WHERE doc_no = p_doc_no AND version = v_saved_version;
    UPDATE pwp_codes
    SET customer_id = v_customer_id, updated_at = now()
    WHERE source_doc_no = p_doc_no;
  END IF;

  IF (p_apply_warehouse AND p_warehouse_id IS NOT NULL) OR p_apply_delivery_date THEN
    -- so-line-freeze rule 3: a live downstream line naming no SO line.
    v_unlinked := EXISTS (
      SELECT 1 FROM delivery_order_items doi
      JOIN delivery_orders d ON d.id = doi.delivery_order_id
      WHERE d.so_doc_no = p_doc_no
        AND upper(btrim(COALESCE(d.status::text, ''))) <> 'CANCELLED'
        AND doi.so_item_id IS NULL
    ) OR EXISTS (
      SELECT 1 FROM sales_invoice_items sii
      JOIN sales_invoices s ON s.id = sii.sales_invoice_id
      WHERE s.so_doc_no = p_doc_no
        AND upper(btrim(COALESCE(s.status::text, ''))) <> 'CANCELLED'
        AND sii.so_item_id IS NULL AND sii.do_item_id IS NULL
    );
    -- so-line-freeze rule 1: lines a live delivery order / invoice line names.
    SELECT COALESCE(array_agg(DISTINCT x.id), ARRAY[]::uuid[]) INTO v_frozen
    FROM (
      SELECT doi.so_item_id AS id
      FROM delivery_order_items doi
      JOIN delivery_orders d ON d.id = doi.delivery_order_id
      WHERE doi.so_item_id IN (SELECT i.id FROM mfg_sales_order_items i WHERE i.doc_no = p_doc_no)
        AND upper(btrim(COALESCE(d.status::text, ''))) <> 'CANCELLED'
      UNION
      SELECT sii.so_item_id
      FROM sales_invoice_items sii
      JOIN sales_invoices s ON s.id = sii.sales_invoice_id
      WHERE sii.so_item_id IN (SELECT i.id FROM mfg_sales_order_items i WHERE i.doc_no = p_doc_no)
        AND upper(btrim(COALESCE(s.status::text, ''))) <> 'CANCELLED'
    ) x;
  END IF;

  IF p_apply_warehouse AND p_warehouse_id IS NOT NULL AND NOT v_unlinked THEN
    UPDATE mfg_sales_order_items
    SET warehouse_id = p_warehouse_id
    WHERE doc_no = p_doc_no AND cancelled = false
      AND NOT (id = ANY(v_frozen))
      AND (warehouse_id IS NULL
           OR (p_rebind_line_ids IS NOT NULL AND id = ANY(p_rebind_line_ids)));
  END IF;
  IF p_apply_delivery_date AND NOT v_unlinked THEN
    UPDATE mfg_sales_order_items
    SET line_delivery_date = p_delivery_date,
        line_delivery_date_overridden = false
    WHERE doc_no = p_doc_no
      AND NOT (id = ANY(v_frozen));
  END IF;

  RETURN QUERY SELECT true, v_saved_version, v_customer_id, NULL::text;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.apply_so_header_followers(p_doc_no text, p_version integer, p_recustomer boolean DEFAULT false, p_customer_name text DEFAULT NULL::text, p_customer_phone text DEFAULT NULL::text, p_customer_email text DEFAULT NULL::text, p_apply_warehouse boolean DEFAULT false, p_warehouse_id uuid DEFAULT NULL::uuid, p_apply_delivery_date boolean DEFAULT false, p_delivery_date date DEFAULT NULL::date)
 RETURNS TABLE(applied boolean, resolved_customer_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'pg_temp'
AS $function$ DECLARE v_version integer; v_customer_id uuid; BEGIN SELECT version INTO v_version FROM mfg_sales_orders WHERE doc_no = p_doc_no FOR UPDATE; IF NOT FOUND OR v_version <> p_version THEN RETURN QUERY SELECT false, NULL::uuid; RETURN; END IF; IF p_recustomer AND NULLIF(btrim(p_customer_name), '') IS NOT NULL AND NULLIF(btrim(p_customer_phone), '') IS NOT NULL THEN v_customer_id := upsert_customer_by_name_phone(p_customer_name, p_customer_phone, p_customer_email); UPDATE mfg_sales_orders SET customer_id = v_customer_id WHERE doc_no = p_doc_no AND version = p_version; UPDATE pwp_codes SET customer_id = v_customer_id, updated_at = now() WHERE source_doc_no = p_doc_no; END IF; IF p_apply_warehouse AND p_warehouse_id IS NOT NULL THEN UPDATE mfg_sales_order_items SET warehouse_id = p_warehouse_id WHERE doc_no = p_doc_no AND cancelled = false AND warehouse_id IS NULL; END IF; IF p_apply_delivery_date THEN UPDATE mfg_sales_order_items SET line_delivery_date = p_delivery_date, line_delivery_date_overridden = false WHERE doc_no = p_doc_no; END IF; RETURN QUERY SELECT true, v_customer_id; END; $function$;

CREATE OR REPLACE FUNCTION scm.canonicalize_my_state(input text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  norm text;
BEGIN
  IF input IS NULL THEN RETURN NULL; END IF;
  norm := btrim(input);
  IF norm = '' THEN RETURN input; END IF;

  -- Fast path: already canonical.
  IF norm IN (
    'Johor','Kedah','Kelantan','Kuala Lumpur','Labuan','Melaka',
    'Negeri Sembilan','Pahang','Perak','Perlis','Pulau Pinang',
    'Putrajaya','Sabah','Sarawak','Selangor','Terengganu'
  ) THEN
    RETURN norm;
  END IF;

  -- Match case- and separator-insensitively against every historical spelling.
  -- Normalise the key: uppercase, REPLACE dots with a space (not drop them),
  -- then collapse whitespace. Dot-to-space is what makes 'P.PINANG',
  -- 'P. PINANG' and 'P PINANG' all collapse to the same key. Keep in sync
  -- with `probeKey` in backend/src/scm/lib/canonical-state.ts.
  norm := upper(norm);
  norm := replace(norm, '.', ' ');
  norm := regexp_replace(norm, '\s+', ' ', 'g');
  norm := btrim(norm);

  RETURN CASE norm
    -- PMS UPPERCASE list (Projects.tsx PROJECT_STATES / ProjectMaintenance MY_STATES).
    WHEN 'JOHOR'            THEN 'Johor'
    WHEN 'KEDAH'            THEN 'Kedah'
    WHEN 'KELANTAN'         THEN 'Kelantan'
    WHEN 'KL'               THEN 'Kuala Lumpur'
    WHEN 'KUALA LUMPUR'     THEN 'Kuala Lumpur'
    WHEN 'WP KUALA LUMPUR'  THEN 'Kuala Lumpur'
    WHEN 'W P KUALA LUMPUR' THEN 'Kuala Lumpur'
    WHEN 'WILAYAH PERSEKUTUAN KUALA LUMPUR' THEN 'Kuala Lumpur'
    WHEN 'LABUAN'           THEN 'Labuan'
    WHEN 'WP LABUAN'        THEN 'Labuan'
    WHEN 'W P LABUAN'       THEN 'Labuan'
    WHEN 'MELAKA'           THEN 'Melaka'
    WHEN 'MALACCA'          THEN 'Melaka'
    WHEN 'NEGERI SEMBILAN'  THEN 'Negeri Sembilan'
    WHEN 'NS'               THEN 'Negeri Sembilan'
    WHEN 'N S'              THEN 'Negeri Sembilan'
    WHEN 'N SEMBILAN'       THEN 'Negeri Sembilan'
    WHEN 'PAHANG'           THEN 'Pahang'
    WHEN 'PENANG'           THEN 'Pulau Pinang'
    WHEN 'PULAU PINANG'     THEN 'Pulau Pinang'
    WHEN 'P PINANG'         THEN 'Pulau Pinang'
    WHEN 'PERAK'            THEN 'Perak'
    WHEN 'PERLIS'           THEN 'Perlis'
    WHEN 'PUTRAJAYA'        THEN 'Putrajaya'
    WHEN 'WP PUTRAJAYA'     THEN 'Putrajaya'
    WHEN 'W P PUTRAJAYA'    THEN 'Putrajaya'
    WHEN 'SABAH'            THEN 'Sabah'
    WHEN 'SARAWAK'          THEN 'Sarawak'
    WHEN 'SELANGOR'         THEN 'Selangor'
    WHEN 'TERENGGANU'       THEN 'Terengganu'
    WHEN 'TRENGGANU'        THEN 'Terengganu'
    -- Unknown / foreign — return the ORIGINAL string, not the uppercase probe.
    ELSE input
  END;
END $function$;

CREATE OR REPLACE FUNCTION scm.canonicalize_venue(input text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  trimmed text;
  k text;
BEGIN
  IF input IS NULL THEN RETURN NULL; END IF;
  trimmed := btrim(input);
  IF trimmed = '' THEN RETURN input; END IF;

  -- The lookup key, byte-for-byte the same rule as `venueKey()` in
  -- canonical-venue.ts: lower-case, trimmed, inner whitespace collapsed.
  k := lower(regexp_replace(trimmed, '\s+', ' ', 'g'));

  RETURN CASE k
    -- canonical "2990s PJ"
    WHEN 'pj showroom' THEN '2990s PJ'
    WHEN 'pj-showroom' THEN '2990s PJ'
    WHEN 'pjshowroom'  THEN '2990s PJ'
    WHEN '2990s pj'    THEN '2990s PJ'
    WHEN '2990spj'     THEN '2990s PJ'
    WHEN '2990 pj'     THEN '2990s PJ'
    WHEN '2990pj'      THEN '2990s PJ'
    -- Unknown venue: trimmed, otherwise unchanged.
    ELSE trimmed
  END;
END $function$;

CREATE OR REPLACE FUNCTION scm.count_orphan_slips()
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'scm', 'pg_temp'
AS $function$
  SELECT COUNT(*)::integer
    FROM pending_slip_uploads
   WHERE status IN ('pending','uploaded')
     AND expires_at < now();
$function$;

CREATE OR REPLACE FUNCTION scm.create_product_with_pricing(p jsonb, p_company_id bigint DEFAULT NULL::bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'scm', 'pg_temp'
AS $function$ DECLARE v_product_id uuid; v_kind text := p->>'pricingKind'; v_company_id bigint := COALESCE(p_company_id, (SELECT id FROM public.companies WHERE code = 'HOUZS')); BEGIN INSERT INTO products (sku, category_id, series_id, pricing_kind, name, detail, size_display, img_key, thumb_key, stock, low_at, visible, flat_price, recliner_upgrade_price, company_id) VALUES (p->>'sku', p->>'categoryId', NULLIF(p->>'seriesId', ''), v_kind::pricing_kind, p->>'name', NULLIF(p->>'detail', ''), NULLIF(p->>'sizeDisplay', ''), p->>'imgKey', p->>'thumbKey', COALESCE((p->>'stock')::int, 0), COALESCE((p->>'lowAt')::int, 5), COALESCE((p->>'visible')::boolean, true), CASE WHEN v_kind = 'flat' THEN (p->>'flatPrice')::int ELSE NULL END, CASE WHEN v_kind = 'sofa_build' THEN (p->>'reclinerUpgradePrice')::int ELSE NULL END, v_company_id) RETURNING id INTO v_product_id; IF v_kind = 'sofa_build' THEN INSERT INTO product_compartments (product_id, compartment_id, active, price, company_id) SELECT v_product_id, (r->>'compartmentId')::text, (r->>'active')::boolean, (r->>'price')::int, v_company_id FROM jsonb_array_elements(p->'compartments') r; INSERT INTO product_bundles (product_id, bundle_id, active, price, company_id) SELECT v_product_id, (r->>'bundleId')::text, (r->>'active')::boolean, (r->>'price')::int, v_company_id FROM jsonb_array_elements(p->'bundles') r; INSERT INTO product_fabrics (product_id, fabric_id, active, surcharge, company_id) SELECT v_product_id, (r->>'fabricId')::text, (r->>'active')::boolean, (r->>'surcharge')::int, v_company_id FROM jsonb_array_elements(COALESCE(p->'fabrics', '[]'::jsonb)) r; ELSIF v_kind = 'size_variants' THEN INSERT INTO product_size_variants (product_id, size_id, active, price, company_id) SELECT v_product_id, (r->>'sizeId')::text, (r->>'active')::boolean, (r->>'price')::int, v_company_id FROM jsonb_array_elements(p->'sizes') r; END IF; RETURN v_product_id; END; $function$;

CREATE OR REPLACE FUNCTION scm.enqueue_vp_outbox()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'public'
AS $function$
BEGIN
  BEGIN
    INSERT INTO scm.venture_portal_outbox (doc_no, op)
    VALUES (COALESCE(NEW.doc_no, OLD.doc_no), TG_OP)
    ON CONFLICT (doc_no) WHERE status = 'pending' DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  RETURN NULL;
END
$function$;

CREATE OR REPLACE FUNCTION scm.enqueue_vp_outbox_child()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'public'
AS $function$
DECLARE
  keycol text := TG_ARGV[0];
  dn     text;
BEGIN
  BEGIN
    dn := COALESCE(to_jsonb(NEW) ->> keycol, to_jsonb(OLD) ->> keycol);
    IF dn IS NOT NULL THEN
      INSERT INTO scm.venture_portal_outbox (doc_no, op)
      VALUES (dn, TG_OP || ':' || TG_TABLE_NAME)
      ON CONFLICT (doc_no) WHERE status = 'pending' DO NOTHING;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  RETURN NULL;
END
$function$;

CREATE OR REPLACE FUNCTION scm.enqueue_vp_outbox_project()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'public'
AS $function$
BEGIN
  BEGIN
    INSERT INTO scm.venture_portal_outbox (doc_no, op)
    SELECT so.doc_no, 'UPDATE:projects'
      FROM scm.mfg_sales_orders so
     WHERE so.project_id = NEW.id
    ON CONFLICT (doc_no) WHERE status = 'pending' DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  RETURN NULL;
END
$function$;

CREATE OR REPLACE FUNCTION scm.fn_check_je_balanced()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  debit_sum INTEGER;
  credit_sum INTEGER;
BEGIN
  IF NEW.posted = TRUE AND (OLD.posted IS DISTINCT FROM TRUE) THEN
    SELECT COALESCE(SUM(debit_sen), 0), COALESCE(SUM(credit_sen), 0)
      INTO debit_sum, credit_sum
      FROM journal_entry_lines WHERE journal_entry_id = NEW.id;

    IF debit_sum <> credit_sum THEN
      RAISE EXCEPTION 'Journal entry % is not balanced: debit=% credit=%',
        NEW.je_no, debit_sum, credit_sum;
    END IF;

    IF debit_sum = 0 THEN
      RAISE EXCEPTION 'Journal entry % has no lines', NEW.je_no;
    END IF;

    NEW.total_debit_sen  := debit_sum;
    NEW.total_credit_sen := credit_sum;
    NEW.posted_at        := COALESCE(NEW.posted_at, now());
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.fn_consume_fifo(p_warehouse_id uuid, p_product_code text, p_variant_key text, p_qty_needed integer, p_source_doc_type text, p_source_doc_id uuid, p_source_doc_no text, p_movement_id uuid, p_created_by uuid)
 RETURNS TABLE(total_cost_sen integer, qty_short integer)
 LANGUAGE plpgsql
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_lot        RECORD;
  v_take       INTEGER;
  v_remaining  INTEGER := p_qty_needed;
  v_total_cost INTEGER := 0;
BEGIN
  FOR v_lot IN
    SELECT id, qty_remaining, unit_cost_sen
      FROM inventory_lots
     WHERE warehouse_id = p_warehouse_id
       AND item_code = p_product_code
       AND variant_key  = p_variant_key
       AND qty_remaining > 0
     ORDER BY received_at ASC, id ASC
     FOR UPDATE
  LOOP
    EXIT WHEN v_remaining <= 0;
    v_take := LEAST(v_lot.qty_remaining, v_remaining);
    v_total_cost := v_total_cost + (v_take * v_lot.unit_cost_sen);
    v_remaining := v_remaining - v_take;

    UPDATE inventory_lots
       SET qty_remaining = qty_remaining - v_take
     WHERE id = v_lot.id;

    INSERT INTO inventory_lot_consumptions (
      lot_id, warehouse_id, item_code, variant_key,
      qty_consumed, unit_cost_sen, total_cost_sen,
      source_doc_type, source_doc_id, source_doc_no, movement_id, created_by
    ) VALUES (
      v_lot.id, p_warehouse_id, p_product_code, p_variant_key,
      v_take, v_lot.unit_cost_sen, v_take * v_lot.unit_cost_sen,
      p_source_doc_type, p_source_doc_id, p_source_doc_no, p_movement_id, p_created_by
    );
  END LOOP;

  RETURN QUERY SELECT v_total_cost, GREATEST(v_remaining, 0);
END;
$function$;

CREATE OR REPLACE FUNCTION scm.fn_consume_fifo_batch(p_warehouse_id uuid, p_product_code text, p_variant_key text, p_qty_needed integer, p_batch_no text, p_source_doc_type text, p_source_doc_id uuid, p_source_doc_no text, p_movement_id uuid, p_created_by uuid)
 RETURNS TABLE(total_cost_sen integer, qty_short integer)
 LANGUAGE plpgsql
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_lot        RECORD;
  v_take       INTEGER;
  v_remaining  INTEGER := p_qty_needed;
  v_total_cost INTEGER := 0;
BEGIN
  FOR v_lot IN
    SELECT id, qty_remaining, unit_cost_sen
      FROM inventory_lots
     WHERE warehouse_id = p_warehouse_id
       AND item_code = p_product_code
       AND variant_key  = p_variant_key
       AND batch_no     = p_batch_no
       AND qty_remaining > 0
     ORDER BY received_at ASC, id ASC
     FOR UPDATE
  LOOP
    EXIT WHEN v_remaining <= 0;
    v_take := LEAST(v_lot.qty_remaining, v_remaining);
    v_total_cost := v_total_cost + (v_take * v_lot.unit_cost_sen);
    v_remaining := v_remaining - v_take;

    UPDATE inventory_lots
       SET qty_remaining = qty_remaining - v_take
     WHERE id = v_lot.id;

    INSERT INTO inventory_lot_consumptions (
      lot_id, warehouse_id, item_code, variant_key,
      qty_consumed, unit_cost_sen, total_cost_sen,
      source_doc_type, source_doc_id, source_doc_no, movement_id, created_by
    ) VALUES (
      v_lot.id, p_warehouse_id, p_product_code, p_variant_key,
      v_take, v_lot.unit_cost_sen, v_take * v_lot.unit_cost_sen,
      p_source_doc_type, p_source_doc_id, p_source_doc_no, p_movement_id, p_created_by
    );
  END LOOP;

  RETURN QUERY SELECT v_total_cost, GREATEST(v_remaining, 0);
END;
$function$;

CREATE OR REPLACE FUNCTION scm.fn_do_header_delete_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'public'
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1 FROM scm.inventory_movements m
     WHERE m.source_doc_type::text = 'DO'
       AND (m.source_doc_no = OLD.do_number OR m.source_doc_id::text = OLD.id::text)
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = 'check_violation',
      MESSAGE = format('do_header_integrity: %s has inventory movements and cannot be deleted', OLD.do_number),
      HINT = 'Goods moved against this delivery order. Set status = CANCELLED instead of deleting the row.';
  END IF;
  RETURN OLD;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.fn_do_line_integrity_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'public'
AS $function$
DECLARE
  hdr       record;
  remaining integer;
  moved     boolean;
BEGIN
  IF OLD.delivery_order_id IS NULL THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.delivery_order_id IS NOT DISTINCT FROM OLD.delivery_order_id THEN
    RETURN NULL;
  END IF;

  SELECT d.id, d.do_number, upper(coalesce(d.status::text, '')) AS status
    INTO hdr
    FROM scm.delivery_orders d
   WHERE d.id = OLD.delivery_order_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  IF hdr.status IN ('DRAFT', 'CANCELLED') THEN
    RETURN NULL;
  END IF;

  SELECT count(*) INTO remaining
    FROM scm.delivery_order_items i
   WHERE i.delivery_order_id = OLD.delivery_order_id;
  IF remaining > 0 THEN
    RETURN NULL;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM scm.inventory_movements m
     WHERE m.movement_type::text = 'OUT'
       AND m.source_doc_type::text = 'DO'
       AND (m.source_doc_no = hdr.do_number OR m.source_doc_id::text = hdr.id::text)
  ) INTO moved;

  IF moved OR hdr.status <> 'LOADED' THEN
    RAISE EXCEPTION USING
      ERRCODE = 'check_violation',
      MESSAGE = format('do_line_integrity: %s (%s) would be left with no line rows', hdr.do_number, hdr.status),
      HINT = 'A shipped delivery order must keep the lines that say what shipped. Cancel the document, or reduce a line, instead of removing every row.';
  END IF;
  RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.fn_inventory_movement_fifo()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_result    RECORD;
  v_fallback  RECORD;
  v_abs_qty   INTEGER;
  v_cost      INTEGER;
  v_short     INTEGER;
  v_avg_cost  INTEGER;
  v_unit_cost INTEGER;
BEGIN
  IF NEW.movement_type = 'IN' THEN
    INSERT INTO inventory_lots (
      warehouse_id, item_code, variant_key, product_name,
      qty_received, qty_remaining, unit_cost_sen,
      received_at, source_doc_type, source_doc_id, source_doc_no,
      movement_id, created_by, batch_no, company_id
    ) VALUES (
      NEW.warehouse_id, NEW.item_code, NEW.variant_key, NEW.product_name,
      NEW.qty, NEW.qty, COALESCE(NEW.unit_cost_sen, 0),
      NEW.created_at,
      NEW.source_doc_type, NEW.source_doc_id, NEW.source_doc_no,
      NEW.id, NEW.performed_by, NEW.batch_no, NEW.company_id
    );
    UPDATE inventory_movements
       SET total_cost_sen = NEW.qty * COALESCE(NEW.unit_cost_sen, 0)
     WHERE id = NEW.id;

  ELSIF NEW.movement_type = 'OUT' THEN
    v_abs_qty := ABS(NEW.qty);
    IF NEW.batch_no IS NOT NULL THEN
      -- Exact dye-lot batch consume first (sofa set stays colour-matched).
      SELECT * INTO v_result
        FROM fn_consume_fifo_batch(
          NEW.warehouse_id, NEW.item_code, NEW.variant_key, v_abs_qty, NEW.batch_no,
          NEW.source_doc_type, NEW.source_doc_id, NEW.source_doc_no,
          NEW.id, NEW.performed_by
        );
      v_cost  := v_result.total_cost_sen;
      v_short := v_result.qty_short;
      -- Ledger-divergence fix (0195): the exact batch matched no (or too few) open
      -- lots. Rather than DISCARD the short (leaving the OUT uncosted + the lots
      -- un-decremented forever — the MAKOTO false-short), fall back to plain
      -- product+variant FIFO (any batch) for the residual so present stock of the
      -- same SKU is consumed + costed. Genuine shorts (no stock at all) survive
      -- the fallback and stay on the 0154 retro-cost path, unchanged.
      IF v_short > 0 THEN
        SELECT * INTO v_fallback
          FROM fn_consume_fifo(
            NEW.warehouse_id, NEW.item_code, NEW.variant_key, v_short,
            NEW.source_doc_type, NEW.source_doc_id, NEW.source_doc_no,
            NEW.id, NEW.performed_by
          );
        v_cost  := v_cost + v_fallback.total_cost_sen;
        v_short := v_fallback.qty_short;
      END IF;
    ELSE
      SELECT * INTO v_result
        FROM fn_consume_fifo(
          NEW.warehouse_id, NEW.item_code, NEW.variant_key, v_abs_qty,
          NEW.source_doc_type, NEW.source_doc_id, NEW.source_doc_no,
          NEW.id, NEW.performed_by
        );
      v_cost  := v_result.total_cost_sen;
      v_short := v_result.qty_short;
    END IF;
    UPDATE inventory_movements
       SET total_cost_sen = v_cost,
           unit_cost_sen  = CASE WHEN v_abs_qty > 0
                                 THEN v_cost / v_abs_qty
                                 ELSE 0 END
     WHERE id = NEW.id;

  ELSIF NEW.movement_type = 'ADJUSTMENT' THEN
    IF NEW.qty > 0 THEN
      SELECT CASE WHEN SUM(qty_remaining) > 0
                  THEN SUM(qty_remaining * unit_cost_sen) / SUM(qty_remaining)
                  ELSE 0 END
        INTO v_avg_cost
        FROM inventory_lots
       WHERE warehouse_id = NEW.warehouse_id
         AND item_code = NEW.item_code
         AND variant_key  = NEW.variant_key
         AND qty_remaining > 0;

      v_unit_cost := COALESCE(NULLIF(NEW.unit_cost_sen, 0), v_avg_cost, 0);

      INSERT INTO inventory_lots (
        warehouse_id, item_code, variant_key, product_name,
        qty_received, qty_remaining, unit_cost_sen,
        received_at, source_doc_type, source_doc_id, source_doc_no,
        movement_id, created_by, batch_no, company_id
      ) VALUES (
        NEW.warehouse_id, NEW.item_code, NEW.variant_key, NEW.product_name,
        NEW.qty, NEW.qty, v_unit_cost,
        NEW.created_at,
        NEW.source_doc_type, NEW.source_doc_id, NEW.source_doc_no,
        NEW.id, NEW.performed_by, NEW.batch_no, NEW.company_id
      );
      UPDATE inventory_movements
         SET total_cost_sen = NEW.qty * v_unit_cost,
             unit_cost_sen  = v_unit_cost
       WHERE id = NEW.id;

    ELSIF NEW.qty < 0 THEN
      v_abs_qty := ABS(NEW.qty);
      IF NEW.batch_no IS NOT NULL THEN
        SELECT * INTO v_result
          FROM fn_consume_fifo_batch(
            NEW.warehouse_id, NEW.item_code, NEW.variant_key, v_abs_qty, NEW.batch_no,
            NEW.source_doc_type, NEW.source_doc_id, NEW.source_doc_no,
            NEW.id, NEW.performed_by
          );
        v_cost  := v_result.total_cost_sen;
        v_short := v_result.qty_short;
        -- Same batch-drift fallback as the OUT branch: a batched write-off that
        -- matches no exact-batch lot consumes present same-SKU stock plain-FIFO
        -- instead of silently stranding the units.
        IF v_short > 0 THEN
          SELECT * INTO v_fallback
            FROM fn_consume_fifo(
              NEW.warehouse_id, NEW.item_code, NEW.variant_key, v_short,
              NEW.source_doc_type, NEW.source_doc_id, NEW.source_doc_no,
              NEW.id, NEW.performed_by
            );
          v_cost  := v_cost + v_fallback.total_cost_sen;
          v_short := v_fallback.qty_short;
        END IF;
      ELSE
        SELECT * INTO v_result
          FROM fn_consume_fifo(
            NEW.warehouse_id, NEW.item_code, NEW.variant_key, v_abs_qty,
            NEW.source_doc_type, NEW.source_doc_id, NEW.source_doc_no,
            NEW.id, NEW.performed_by
          );
        v_cost  := v_result.total_cost_sen;
        v_short := v_result.qty_short;
      END IF;
      UPDATE inventory_movements
         SET total_cost_sen = v_cost,
             unit_cost_sen  = CASE WHEN v_abs_qty > 0
                                   THEN v_cost / v_abs_qty
                                   ELSE 0 END
       WHERE id = NEW.id;
    END IF;
    -- NEW.qty = 0 ADJUSTMENT is a no-op.
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.fn_mfg_so_item_delete_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'public'
AS $function$
BEGIN
  INSERT INTO scm.mfg_so_item_deletions (
    so_item_id, doc_no, item_code, qty, company_id,
    jwt_claims, db_user, application_name, backend_pid, txid
  ) VALUES (
    OLD.id, OLD.doc_no, OLD.item_code, OLD.qty, OLD.company_id,
    /* PostgREST sets this GUC per request; absent (and therefore NULL) for a
       psql session, a migration or pg_cron. `true` = missing_ok, so this never
       raises and can never block the delete it is only observing. */
    NULLIF(current_setting('request.jwt.claims', true), '')::jsonb,
    current_user,
    current_setting('application_name', true),
    pg_backend_pid(),
    txid_current()
  );
  RETURN OLD;
EXCEPTION WHEN OTHERS THEN
  /* AN AUDIT MUST NEVER BREAK THE OPERATION IT WATCHES. A malformed JWT claim
     or a full disk would otherwise turn "remove a line" into a 500 for the
     operator. Swallow, and let the sentinel's own alarm be the thing that
     notices this table has gone quiet. */
  RETURN OLD;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.fn_po_item_alloc_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_line_qty  integer;
  v_other_sum integer;
BEGIN
  -- Lock the parent line: serialises two concurrent allocation writers on the
  -- same line, so both cannot pass the sum check with the pre-image.
  SELECT qty INTO v_line_qty
    FROM scm.purchase_order_items
   WHERE id = NEW.purchase_order_item_id
   FOR UPDATE;
  IF v_line_qty IS NULL THEN
    RAISE EXCEPTION 'po_line_not_found: purchase_order_item % does not exist', NEW.purchase_order_item_id;
  END IF;

  SELECT COALESCE(SUM(qty), 0) INTO v_other_sum
    FROM scm.purchase_order_item_allocations
   WHERE purchase_order_item_id = NEW.purchase_order_item_id
     AND id <> NEW.id;

  IF v_other_sum + NEW.qty > v_line_qty THEN
    RAISE EXCEPTION 'allocation_exceeds_line_qty: allocations % + % exceed line qty %',
      v_other_sum, NEW.qty, v_line_qty;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.fn_po_item_qty_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_alloc_sum integer;
BEGIN
  -- Only a shrink can break the invariant; skip the common no-change/grow path.
  IF NEW.qty >= OLD.qty THEN
    RETURN NEW;
  END IF;
  SELECT COALESCE(SUM(qty), 0) INTO v_alloc_sum
    FROM scm.purchase_order_item_allocations
   WHERE purchase_order_item_id = NEW.id;
  IF v_alloc_sum > NEW.qty THEN
    RAISE EXCEPTION 'line_qty_below_allocated: line qty % is below the % already allocated - delete or shrink the line''s allocations first',
      NEW.qty, v_alloc_sum;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.fn_reconcile_dropship_batch(p_warehouse_id uuid, p_product_code text, p_variant_key text, p_batch_no text, p_created_by uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_out         RECORD;
  v_lot         RECORD;
  v_already     INTEGER;
  v_short       INTEGER;
  v_take        INTEGER;
  v_consumed    INTEGER := 0;
BEGIN
  IF p_batch_no IS NULL THEN
    RETURN 0;
  END IF;

  FOR v_out IN
    SELECT m.id, m.qty, m.source_doc_type, m.source_doc_id, m.source_doc_no
      FROM scm.inventory_movements m
     WHERE m.movement_type = 'OUT'
       AND m.warehouse_id  = p_warehouse_id
       AND m.item_code  = p_product_code
       AND COALESCE(m.variant_key, '') = COALESCE(p_variant_key, '')
       AND m.batch_no      = p_batch_no
       AND m.source_doc_type = 'DO'
       AND EXISTS (
         SELECT 1 FROM scm.delivery_orders d
          WHERE d.id = m.source_doc_id
            AND UPPER(COALESCE(d.status::text, '')) <> 'CANCELLED'
            AND (
              d.is_dropship = TRUE
              OR EXISTS (
                SELECT 1 FROM scm.delivery_order_items di
                 WHERE di.delivery_order_id       = d.id
                   AND di.committed_po_batch_no   = p_batch_no
                   AND di.item_code               = p_product_code
                   /* Scoped to the VARIANT too, for symmetry with the OUT loop
                      above (which is variant-keyed). Two lines of one DO can
                      carry the same item_code in different fabrics; without
                      this they cross-claim each other's batch. */
                   AND COALESCE(di.committed_variant_key, '') = COALESCE(p_variant_key, '')
              )
            )
       )
     ORDER BY m.created_at ASC, m.id ASC
     FOR UPDATE OF m
  LOOP
    SELECT COALESCE(SUM(qty_consumed), 0) INTO v_already
      FROM scm.inventory_lot_consumptions
     WHERE movement_id = v_out.id;
    v_short := ABS(v_out.qty) - v_already;
    CONTINUE WHEN v_short <= 0;

    FOR v_lot IN
      SELECT id, qty_remaining, unit_cost_sen, company_id
        FROM scm.inventory_lots
       WHERE warehouse_id = p_warehouse_id
         AND item_code = p_product_code
         AND COALESCE(variant_key, '') = COALESCE(p_variant_key, '')
         AND batch_no     = p_batch_no
         AND qty_remaining > 0
       ORDER BY received_at ASC, id ASC
       FOR UPDATE
    LOOP
      EXIT WHEN v_short <= 0;
      v_take := LEAST(v_lot.qty_remaining, v_short);

      UPDATE scm.inventory_lots
         SET qty_remaining = qty_remaining - v_take
       WHERE id = v_lot.id;

      INSERT INTO scm.inventory_lot_consumptions (
        lot_id, warehouse_id, item_code, variant_key,
        qty_consumed, unit_cost_sen, total_cost_sen,
        source_doc_type, source_doc_id, source_doc_no, movement_id, created_by,
        company_id
      ) VALUES (
        v_lot.id, p_warehouse_id, p_product_code, p_variant_key,
        v_take, v_lot.unit_cost_sen, v_take * v_lot.unit_cost_sen,
        v_out.source_doc_type, v_out.source_doc_id, v_out.source_doc_no, v_out.id, p_created_by,
        v_lot.company_id
      );

      v_short    := v_short - v_take;
      v_consumed := v_consumed + v_take;
    END LOOP;

    UPDATE scm.inventory_movements m
       SET total_cost_sen = sub.total_cost,
           unit_cost_sen  = CASE WHEN ABS(m.qty) > 0 THEN sub.total_cost / ABS(m.qty) ELSE 0 END
      FROM (
        SELECT COALESCE(SUM(total_cost_sen), 0) AS total_cost
          FROM scm.inventory_lot_consumptions
         WHERE movement_id = v_out.id
      ) sub
     WHERE m.id = v_out.id;
  END LOOP;

  RETURN v_consumed;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.fn_reconcile_uncosted_out(p_warehouse_id uuid, p_product_code text, p_variant_key text, p_before_ts timestamp with time zone, p_created_by uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_out       RECORD;
  v_lot       RECORD;
  v_already   INTEGER;
  v_short     INTEGER;
  v_take      INTEGER;
  v_consumed  INTEGER := 0;
BEGIN
  FOR v_out IN
    SELECT m.id, m.qty, m.company_id,
           m.source_doc_type, m.source_doc_id, m.source_doc_no
      FROM scm.inventory_movements m
     WHERE m.movement_type   = 'OUT'
       AND m.warehouse_id     = p_warehouse_id
       AND m.item_code     = p_product_code
       AND COALESCE(m.variant_key, '') = COALESCE(p_variant_key, '')
       AND m.source_doc_type  = 'DO'
       AND m.created_at       < p_before_ts
       AND EXISTS (
         SELECT 1 FROM scm.delivery_orders d
          WHERE d.id = m.source_doc_id
            AND COALESCE(d.is_dropship, FALSE) = FALSE
            AND UPPER(COALESCE(d.status::text, '')) <> 'CANCELLED'
       )
       /* The mirror exclusion — STRICT-BATCH LINES ONLY (see the header). A
          committed SOFA OUT belongs to the batched reconcile, because costing it
          from an arbitrary lot means another dye lot. A committed MATTRESS OUT
          has no dye lot to protect and MUST stay repairable here, or a cancelled
          / re-raised PO would strand its COGS at RM0 for good — which is what
          this migration exists to stop, not to cause. */
       AND NOT (
         m.batch_no IS NOT NULL
         AND EXISTS (
           SELECT 1 FROM scm.delivery_order_items di
            WHERE di.delivery_order_id     = m.source_doc_id
              AND di.committed_po_batch_no = m.batch_no
              AND di.item_code             = m.item_code
              AND COALESCE(di.committed_variant_key, '') = COALESCE(m.variant_key, '')
              AND di.committed_batch_strict = TRUE
         )
       )
     ORDER BY m.created_at ASC, m.id ASC
     FOR UPDATE OF m
  LOOP
    SELECT COALESCE(SUM(qty_consumed), 0) INTO v_already
      FROM scm.inventory_lot_consumptions
     WHERE movement_id = v_out.id;
    v_short := ABS(v_out.qty) - v_already;
    CONTINUE WHEN v_short <= 0;

    FOR v_lot IN
      SELECT id, qty_remaining, unit_cost_sen, company_id
        FROM scm.inventory_lots
       WHERE warehouse_id = p_warehouse_id
         AND item_code = p_product_code
         AND COALESCE(variant_key, '') = COALESCE(p_variant_key, '')
         AND company_id   = v_out.company_id
         AND qty_remaining > 0
       ORDER BY received_at ASC, id ASC
       FOR UPDATE
    LOOP
      EXIT WHEN v_short <= 0;
      v_take := LEAST(v_lot.qty_remaining, v_short);

      UPDATE scm.inventory_lots
         SET qty_remaining = qty_remaining - v_take
       WHERE id = v_lot.id;

      INSERT INTO scm.inventory_lot_consumptions (
        lot_id, warehouse_id, item_code, variant_key,
        qty_consumed, unit_cost_sen, total_cost_sen,
        source_doc_type, source_doc_id, source_doc_no, movement_id, created_by,
        company_id
      ) VALUES (
        v_lot.id, p_warehouse_id, p_product_code, COALESCE(p_variant_key, ''),
        v_take, v_lot.unit_cost_sen, v_take * v_lot.unit_cost_sen,
        v_out.source_doc_type, v_out.source_doc_id, v_out.source_doc_no,
        v_out.id, p_created_by, v_lot.company_id
      );

      v_short    := v_short - v_take;
      v_consumed := v_consumed + v_take;
    END LOOP;

    UPDATE scm.inventory_movements m
       SET total_cost_sen = sub.total_cost,
           unit_cost_sen  = CASE WHEN ABS(m.qty) > 0
                                 THEN sub.total_cost / ABS(m.qty) ELSE 0 END
      FROM (
        SELECT COALESCE(SUM(total_cost_sen), 0) AS total_cost
          FROM scm.inventory_lot_consumptions
         WHERE movement_id = v_out.id
      ) sub
     WHERE m.id = v_out.id;
  END LOOP;

  RETURN v_consumed;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.fn_return_do_units_at_cost(p_do_id uuid, p_warehouse_id uuid, p_product_code text, p_variant_key text, p_batch_no text, p_qty integer, p_correction_seq integer, p_performed_by uuid, p_notes text)
 RETURNS TABLE(qty_returned integer, qty_costed integer, qty_uncosted integer, cost_restored_sen bigint)
 LANGUAGE plpgsql
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_con       RECORD; -- $
  v_need      INTEGER := p_qty; -- $
  v_take      INTEGER; -- $
  v_costed    INTEGER := 0; -- $
  v_cost      BIGINT  := 0; -- $
  v_in_id     UUID; -- $
  v_doc_no    TEXT; -- $
  v_name      TEXT; -- $
  v_company   BIGINT; -- $
BEGIN
  IF p_qty IS NULL OR p_qty <= 0 THEN
    RETURN QUERY SELECT 0, 0, 0, 0::BIGINT; -- $
    RETURN; -- $
  END IF; -- $

  -- Bucket identity for the balancing row. Read from the DO's own movements so
  -- the IN matches the OUT it compensates (name, doc number, company) instead of
  -- being re-derived from the document and drifting.
  SELECT MAX(m.source_doc_no), MAX(m.product_name), MAX(m.company_id)
    INTO v_doc_no, v_name, v_company
    FROM scm.inventory_movements m
   WHERE m.source_doc_type = 'DO'
     AND m.source_doc_id   = p_do_id
     AND m.warehouse_id    = p_warehouse_id
     AND m.item_code    = p_product_code
     AND COALESCE(m.variant_key, '') = COALESCE(p_variant_key, '')
     AND m.batch_no IS NOT DISTINCT FROM p_batch_no; -- $

  -- 1. Unwind this bucket's lot consumptions, newest first, up to p_qty units.
  --    Each unit goes back to the lot that paid for it, at that lot's cost.
  FOR v_con IN
    SELECT c.id, c.lot_id, c.qty_consumed, c.unit_cost_sen
      FROM scm.inventory_lot_consumptions c
      JOIN scm.inventory_movements mo ON mo.id = c.movement_id
     WHERE mo.source_doc_type = 'DO'
       AND mo.source_doc_id   = p_do_id
       AND mo.movement_type   = 'OUT'
       AND mo.warehouse_id    = p_warehouse_id
       AND mo.item_code    = p_product_code
       AND COALESCE(mo.variant_key, '') = COALESCE(p_variant_key, '')
       AND mo.batch_no IS NOT DISTINCT FROM p_batch_no
     ORDER BY c.created_at DESC, c.id DESC
     FOR UPDATE OF c
  LOOP
    EXIT WHEN v_need <= 0; -- $
    v_take := LEAST(v_need, v_con.qty_consumed); -- $
    IF v_take <= 0 THEN
      CONTINUE; -- $
    END IF; -- $

    UPDATE scm.inventory_lots
       SET qty_remaining = qty_remaining + v_take
     WHERE id = v_con.lot_id; -- $

    IF v_take >= v_con.qty_consumed THEN
      -- Wholly returned: the consumption never happened. Deleting rather than
      -- zeroing matches fn_reverse_do_out — a 0-qty consumption row still reads
      -- as "this DO consumed this lot" to every report that joins on it.
      DELETE FROM scm.inventory_lot_consumptions WHERE id = v_con.id; -- $
    ELSE
      UPDATE scm.inventory_lot_consumptions
         SET qty_consumed  = qty_consumed - v_take,
             total_cost_sen = (qty_consumed - v_take) * COALESCE(unit_cost_sen, 0)
       WHERE id = v_con.id; -- $
    END IF; -- $

    v_costed := v_costed + v_take; -- $
    v_cost   := v_cost + (v_take::BIGINT * COALESCE(v_con.unit_cost_sen, 0)); -- $
    v_need   := v_need - v_take; -- $
  END LOOP; -- $

  -- 2. Restamp every OUT in the bucket from the consumptions that SURVIVED, so
  --    the shipment's COGS is what is still shipped. Same shape as 0088's
  --    re-stamp. An OUT whose consumptions are all gone lands on 0, correctly.
  UPDATE scm.inventory_movements m
     SET total_cost_sen = sub.total_cost,
         unit_cost_sen  = CASE WHEN ABS(m.qty) > 0 THEN sub.total_cost / ABS(m.qty) ELSE 0 END
    FROM (
      SELECT mo.id AS movement_id,
             COALESCE((SELECT SUM(c.total_cost_sen)
                         FROM scm.inventory_lot_consumptions c
                        WHERE c.movement_id = mo.id), 0) AS total_cost
        FROM scm.inventory_movements mo
       WHERE mo.source_doc_type = 'DO'
         AND mo.source_doc_id   = p_do_id
         AND mo.movement_type   = 'OUT'
         AND mo.warehouse_id    = p_warehouse_id
         AND mo.item_code    = p_product_code
         AND COALESCE(mo.variant_key, '') = COALESCE(p_variant_key, '')
         AND mo.batch_no IS NOT DISTINCT FROM p_batch_no
    ) sub
   WHERE m.id = sub.movement_id; -- $

  -- 3. ONE balancing IN so the movement ledger nets to the physical truth. Cost 0
  --    and its minted lot closed: the value went back into the ORIGINAL lots in
  --    step 1, and a second lot here would double-count both stock and cost.
  INSERT INTO scm.inventory_movements (
    movement_type, warehouse_id, item_code, variant_key, product_name,
    qty, batch_no, source_doc_type, source_doc_id, source_doc_no,
    correction_seq, performed_by, notes, company_id
  ) VALUES (
    'IN', p_warehouse_id, p_product_code, COALESCE(p_variant_key, ''), v_name,
    p_qty, p_batch_no, 'DO', p_do_id, v_doc_no,
    p_correction_seq, p_performed_by,
    COALESCE(p_notes, 'Resync: line qty reduced / line deleted (shipped DO).')
      || ' Original lots restored at original cost'
      || CASE WHEN v_need > 0
              THEN ' (' || v_need || ' unit(s) had no cost to return - uncosted at shipment).'
              ELSE '.' END,
    v_company
  ) RETURNING id INTO v_in_id; -- $

  UPDATE scm.inventory_lots SET qty_remaining = 0 WHERE movement_id = v_in_id; -- $
  UPDATE scm.inventory_movements SET total_cost_sen = 0, unit_cost_sen = 0 WHERE id = v_in_id; -- $

  RETURN QUERY SELECT p_qty, v_costed, v_need, v_cost; -- $
END; -- $
$function$;

CREATE OR REPLACE FUNCTION scm.fn_reverse_do_out(p_do_id uuid, p_performed_by uuid, p_batched_only boolean)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_bucket   RECORD; -- $
  v_con      RECORD; -- $
  v_adj_id   UUID; -- $
  v_net      INTEGER; -- $
  v_written  INTEGER := 0; -- $
  v_existing INTEGER; -- $
BEGIN
  -- Idempotency — reversal rows are tagged source_doc_type='ADJUSTMENT' +
  -- this DO's id (same signal the route-side guard checks). Already there ->
  -- the reversal (this fn or the legacy route path) already ran.
  SELECT COUNT(*) INTO v_existing
    FROM scm.inventory_movements
   WHERE source_doc_type = 'ADJUSTMENT'
     AND source_doc_id   = p_do_id; -- $
  IF v_existing > 0 THEN
    RETURN 0; -- $
  END IF; -- $

  FOR v_bucket IN
    SELECT m.warehouse_id,
           m.item_code,
           COALESCE(m.variant_key, '')                                   AS vkey,
           m.batch_no,
           SUM(CASE WHEN m.movement_type = 'OUT' THEN m.qty ELSE 0 END)  AS out_qty,
           SUM(CASE WHEN m.movement_type = 'IN'  THEN m.qty ELSE 0 END)  AS in_qty,
           MAX(m.product_name)                                           AS product_name,
           MAX(m.source_doc_no)                                          AS doc_no,
           MAX(m.company_id)                                             AS company_id
      FROM scm.inventory_movements m
     WHERE m.source_doc_type = 'DO'
       AND m.source_doc_id   = p_do_id
       AND m.movement_type IN ('IN', 'OUT')
       AND (NOT p_batched_only OR m.batch_no IS NOT NULL)
     GROUP BY m.warehouse_id, m.item_code, COALESCE(m.variant_key, ''), m.batch_no
  LOOP
    -- a. Restore every lot consumption linked to this DO's OUT movements in
    --    the bucket (GRN-reconcile consumptions AND normal FIFO-trigger
    --    consumptions alike): the consumed lot gets its qty back at its
    --    ORIGINAL cost, and the consumption row (COGS attribution to a now-
    --    cancelled DO) is deleted. batch_no match is NULL-safe so a plain
    --    (unbatched) bucket restores its own OUT's consumptions too.
    FOR v_con IN
      SELECT c.id, c.lot_id, c.qty_consumed
        FROM scm.inventory_lot_consumptions c
        JOIN scm.inventory_movements mo ON mo.id = c.movement_id
       WHERE mo.source_doc_type = 'DO'
         AND mo.source_doc_id   = p_do_id
         AND mo.movement_type   = 'OUT'
         AND mo.warehouse_id    = v_bucket.warehouse_id
         AND mo.item_code    = v_bucket.item_code
         AND COALESCE(mo.variant_key, '') = v_bucket.vkey
         AND mo.batch_no IS NOT DISTINCT FROM v_bucket.batch_no
       FOR UPDATE OF c
    LOOP
      UPDATE scm.inventory_lots
         SET qty_remaining = qty_remaining + v_con.qty_consumed
       WHERE id = v_con.lot_id; -- $
      DELETE FROM scm.inventory_lot_consumptions WHERE id = v_con.id; -- $
    END LOOP; -- $

    -- b. Zero the OUT movements' cost stamps — their consumptions are gone, so
    --    a stamped cost would be a COGS figure with no ledger backing.
    UPDATE scm.inventory_movements
       SET total_cost_sen = 0, unit_cost_sen = 0
     WHERE source_doc_type = 'DO'
       AND source_doc_id   = p_do_id
       AND movement_type   = 'OUT'
       AND warehouse_id    = v_bucket.warehouse_id
       AND item_code    = v_bucket.item_code
       AND COALESCE(variant_key, '') = v_bucket.vkey
       AND batch_no IS NOT DISTINCT FROM v_bucket.batch_no; -- $

    -- c. Close still-intact lots minted by this DO's OWN delta-IN movements
    --    (a resync qty-decrease wrote an IN whose lot double-counts stock now
    --    that (a) has restored the original lots). Only fully-untouched lots
    --    (qty_remaining = qty_received) are closed — a lot another document
    --    already consumed from is left alone.
    UPDATE scm.inventory_lots l
       SET qty_remaining = 0
     WHERE l.qty_remaining = l.qty_received
       AND l.qty_received > 0
       AND l.movement_id IN (
         SELECT mi.id FROM scm.inventory_movements mi
          WHERE mi.source_doc_type = 'DO'
            AND mi.source_doc_id   = p_do_id
            AND mi.movement_type   = 'IN'
            AND mi.warehouse_id    = v_bucket.warehouse_id
            AND mi.item_code    = v_bucket.item_code
            AND COALESCE(mi.variant_key, '') = v_bucket.vkey
            AND mi.batch_no IS NOT DISTINCT FROM v_bucket.batch_no
       ); -- $

    -- d. One balancing ADJUSTMENT (+net_out) so inventory_balances nets to the
    --    physical truth, then close the lot the trigger's ADJUSTMENT branch
    --    opened: the goods were either restored to their original lots in (a),
    --    or were never physically received (pure drop-ship, C2) — a fresh open
    --    lot here would double-count / be phantom coverage either way.
    v_net := COALESCE(v_bucket.out_qty, 0) - COALESCE(v_bucket.in_qty, 0); -- $
    IF v_net > 0 THEN
      INSERT INTO scm.inventory_movements (
        movement_type, warehouse_id, item_code, variant_key, product_name,
        qty, batch_no, source_doc_type, source_doc_id, source_doc_no,
        performed_by, notes, company_id
      ) VALUES (
        'ADJUSTMENT', v_bucket.warehouse_id, v_bucket.item_code, v_bucket.vkey,
        v_bucket.product_name, v_net, v_bucket.batch_no,
        'ADJUSTMENT', p_do_id, v_bucket.doc_no, p_performed_by,
        CASE WHEN p_batched_only
             THEN 'Drop-ship DO ' || COALESCE(v_bucket.doc_no, p_do_id::text)
                  || ' cancelled - reversing shipment (balance restored, no lot minted)'
             ELSE 'DO ' || COALESCE(v_bucket.doc_no, p_do_id::text)
                  || ' cancelled - original lots restored at original cost, balance-only add-back (no lot minted)'
        END,
        v_bucket.company_id
      ) RETURNING id INTO v_adj_id; -- $

      UPDATE scm.inventory_lots SET qty_remaining = 0 WHERE movement_id = v_adj_id; -- $
      UPDATE scm.inventory_movements SET total_cost_sen = 0, unit_cost_sen = 0 WHERE id = v_adj_id; -- $
      v_written := v_written + 1; -- $
    END IF; -- $
  END LOOP; -- $

  RETURN v_written; -- $
END; -- $
$function$;

CREATE OR REPLACE FUNCTION scm.fn_reverse_dropship_do_out(p_do_id uuid, p_performed_by uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'scm', 'pg_temp'
AS $function$
BEGIN
  RETURN scm.fn_reverse_do_out(p_do_id, p_performed_by, TRUE); -- $
END; -- $
$function$;

CREATE OR REPLACE FUNCTION scm.fn_stock_transfer_apply(p_from_warehouse_id uuid, p_to_warehouse_id uuid, p_source_doc_id uuid, p_source_doc_no text, p_company_id bigint, p_performed_by uuid, p_lines jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_line     JSONB;
  v_qty      INTEGER;
  v_variant  TEXT;
  v_batch    TEXT;
  v_out_id   UUID;
  v_out_qty  INTEGER;
  v_out_cost INTEGER;
  v_in_unit  INTEGER;
  v_moved    INTEGER := 0;
BEGIN
  FOR v_line IN SELECT * FROM jsonb_array_elements(COALESCE(p_lines, '[]'::jsonb))
  LOOP
    v_qty := FLOOR(COALESCE((v_line->>'qty')::numeric, 0))::integer;
    CONTINUE WHEN v_qty <= 0;                       -- mirror JS `if (ln.qty <= 0) continue`
    v_variant := COALESCE(v_line->>'variant_key', '');
    v_batch   := NULLIF(v_line->>'batch_no', '');   -- '' / absent -> NULL -> plain FIFO

    -- 1) OUT @ source. The AFTER-INSERT FIFO trigger consumes the source lots
    --    (FOR UPDATE row locks, held to txn end) and stamps this row's
    --    total_cost_sen via its own UPDATE — visible to us below in this same txn.
    INSERT INTO scm.inventory_movements (
      company_id, movement_type, warehouse_id, item_code, variant_key,
      product_name, qty, source_doc_type, source_doc_id, source_doc_no,
      batch_no, performed_by, notes
    ) VALUES (
      p_company_id, 'OUT', p_from_warehouse_id, v_line->>'item_code', v_variant,
      v_line->>'product_name', v_qty, 'STOCK_TRANSFER', p_source_doc_id, p_source_doc_no,
      v_batch, p_performed_by, 'Transfer to warehouse ' || p_to_warehouse_id::text
    ) RETURNING id INTO v_out_id;

    -- 2) Read the consumed cost the trigger just stamped (same txn sees its own
    --    writes) and derive the IN unit cost = weighted-avg of the source lots.
    SELECT qty, COALESCE(total_cost_sen, 0)
      INTO v_out_qty, v_out_cost
      FROM scm.inventory_movements
     WHERE id = v_out_id;
    v_in_unit := CASE WHEN v_out_qty > 0
                      THEN round(v_out_cost::numeric / v_out_qty)::integer
                      ELSE 0 END;

    -- 3) IN @ destination at that cost. The FIFO trigger opens the dest lot with
    --    the carried cost + batch. If THIS raises, the whole call (including the
    --    OUT above and every prior line) rolls back — stock is never half-moved.
    INSERT INTO scm.inventory_movements (
      company_id, movement_type, warehouse_id, item_code, variant_key,
      product_name, qty, unit_cost_sen, source_doc_type, source_doc_id, source_doc_no,
      batch_no, performed_by, notes
    ) VALUES (
      p_company_id, 'IN', p_to_warehouse_id, v_line->>'item_code', v_variant,
      v_line->>'product_name', v_qty, v_in_unit, 'STOCK_TRANSFER', p_source_doc_id, p_source_doc_no,
      v_batch, p_performed_by, 'Transfer from warehouse ' || p_from_warehouse_id::text
    );

    v_moved := v_moved + 1;
  END LOOP;

  RETURN v_moved;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.jsonb_replace_string_value(j jsonb, p_from text, p_to text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'scm', 'pg_temp'
AS $function$
BEGIN
  CASE jsonb_typeof(j)
    WHEN 'string' THEN
      IF j #>> '{}' = p_from THEN RETURN to_jsonb(p_to); END IF;
      RETURN j;
    WHEN 'array' THEN
      RETURN coalesce((SELECT jsonb_agg(scm.jsonb_replace_string_value(e, p_from, p_to) ORDER BY o)
                         FROM jsonb_array_elements(j) WITH ORDINALITY AS t(e, o)), '[]'::jsonb);
    WHEN 'object' THEN
      RETURN coalesce((SELECT jsonb_object_agg(k, scm.jsonb_replace_string_value(v, p_from, p_to))
                         FROM jsonb_each(j) AS t(k, v)), '{}'::jsonb);
    ELSE
      RETURN j;
  END CASE;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.lease_orphan_slips(p_worker_id text, p_limit integer DEFAULT 100)
 RETURNS TABLE(id uuid, r2_key text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'pg_temp'
AS $function$
BEGIN
  RETURN QUERY
  UPDATE pending_slip_uploads psu
     SET claimed_by = p_worker_id,
         lease_expires_at = now() + INTERVAL '5 minutes'
   WHERE psu.id IN (
     SELECT psu2.id
       FROM pending_slip_uploads psu2
      WHERE psu2.status IN ('pending','uploaded')
        AND psu2.expires_at < now()
        AND (psu2.claimed_by IS NULL OR psu2.lease_expires_at < now())
      ORDER BY psu2.expires_at
      FOR UPDATE SKIP LOCKED
      LIMIT p_limit
   )
   RETURNING psu.id, psu.r2_key;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.mfg_products_retail_price_lock()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  merged  jsonb;
  carried integer := 0;
  readded integer := 0;
BEGIN
  -- 2990 only. Company 1's catalogue is governed by company 1.
  IF NEW.company_id IS DISTINCT FROM 2 THEN
    RETURN NEW;
  END IF;

  IF NEW.seat_height_prices IS NOT DISTINCT FROM OLD.seat_height_prices THEN
    RETURN NEW;
  END IF;

  IF OLD.seat_height_prices IS NULL
     OR jsonb_typeof(OLD.seat_height_prices) <> 'array' THEN
    RETURN NEW;                                   -- nothing stored to protect
  END IF;

  -- Cheap early-out: no stored retail price on this SKU, nothing to defend.
  IF NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(OLD.seat_height_prices) AS e(elem)
    WHERE jsonb_typeof(e.elem->'sellingPriceSen') = 'number'
  ) THEN
    RETURN NEW;
  END IF;

  WITH old_slots AS (
    SELECT e.elem,
           e.elem->>'height'                 AS h,
           COALESCE(e.elem->>'tier', 'PRICE_2') AS t
    FROM jsonb_array_elements(OLD.seat_height_prices) AS e(elem)
  ),
  new_slots AS (
    SELECT e.ord,
           e.elem,
           e.elem->>'height'                 AS h,
           COALESCE(e.elem->>'tier', 'PRICE_2') AS t
    FROM jsonb_array_elements(
           CASE WHEN jsonb_typeof(NEW.seat_height_prices) = 'array'
                THEN NEW.seat_height_prices
                ELSE '[]'::jsonb END) WITH ORDINALITY AS e(elem, ord)
  ),
  kept AS (
    -- incoming slots: retail carried forward when the writer did not name it
    SELECT n.ord::numeric AS ord,
           CASE
             WHEN n.elem ? 'sellingPriceSen' THEN n.elem
             WHEN o.elem ? 'sellingPriceSen'
               THEN n.elem || jsonb_build_object('sellingPriceSen', o.elem->'sellingPriceSen')
             ELSE n.elem
           END AS elem,
           (NOT (n.elem ? 'sellingPriceSen') AND (o.elem ? 'sellingPriceSen')) AS did_carry
    FROM new_slots n
    LEFT JOIN old_slots o ON o.h = n.h AND o.t = n.t
  ),
  back AS (
    -- priced slots the incoming array dropped entirely: put the retail back
    SELECT (1000000 + row_number() OVER (ORDER BY o.h, o.t))::numeric AS ord,
           jsonb_build_object('height', o.h,
                              'tier',   o.t,
                              'sellingPriceSen', o.elem->'sellingPriceSen') AS elem,
           false AS did_carry
    FROM old_slots o
    WHERE jsonb_typeof(o.elem->'sellingPriceSen') = 'number'
      AND NOT EXISTS (SELECT 1 FROM new_slots n WHERE n.h = o.h AND n.t = o.t)
  ),
  u AS (
    SELECT ord, elem, did_carry, 'kept'::text AS src FROM kept
    UNION ALL
    SELECT ord, elem, did_carry, 'back'::text       FROM back
  )
  SELECT jsonb_agg(u.elem ORDER BY u.ord),
         COALESCE(count(*) FILTER (WHERE u.src = 'kept' AND u.did_carry), 0),
         COALESCE(count(*) FILTER (WHERE u.src = 'back'), 0)
    INTO merged, carried, readded
  FROM u;

  IF merged IS NULL THEN                          -- defensive: never blank the row
    RETURN NEW;
  END IF;

  IF merged IS DISTINCT FROM NEW.seat_height_prices THEN
    INSERT INTO scm.retail_price_guard_log
      (company_id, item_code, incoming, stored, applied,
       slots_carried_forward, slots_readded)
    VALUES
      (NEW.company_id, NEW.code, NEW.seat_height_prices, OLD.seat_height_prices,
       merged, carried, readded);
    NEW.seat_height_prices := merged;
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.mfg_sales_orders_canonicalize_venue()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.venue := scm.canonicalize_venue(NEW.venue);
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION scm.mfg_so_sync_access_staff_ids()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.access_staff_ids := (
    SELECT COALESCE(array_agg(DISTINCT s), '{}'::uuid[])
      FROM unnest(
        CASE WHEN NEW.salesperson_id IS NULL THEN '{}'::uuid[]
             ELSE ARRAY[NEW.salesperson_id] END
        || COALESCE(NEW.collaborator_staff_ids, '{}'::uuid[])
      ) AS s
     WHERE s IS NOT NULL
  );
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.next_doc_no_n(p_series text, p_floor integer)
 RETURNS integer
 LANGUAGE sql
AS $function$
  INSERT INTO scm.doc_number_counters AS c (series, next_n, seed_source)
  VALUES (
    p_series,
    GREATEST(COALESCE(p_floor, 0), 0) + 2,
    'self-seeded on first use from the live max (' || GREATEST(COALESCE(p_floor, 0), 0) || ')'
  )
  ON CONFLICT (series) DO UPDATE
     SET next_n     = GREATEST(c.next_n, GREATEST(COALESCE(p_floor, 0), 0) + 1) + 1,
         updated_at = now()
  RETURNING next_n - 1;
$function$;

CREATE OR REPLACE FUNCTION scm.pin_attempt_check(p_staff_id text, p_max integer)
 RETURNS TABLE(allowed boolean, retry_after integer, remaining integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_count integer; -- $
  v_reset timestamptz; -- $
BEGIN
  SELECT a.count, a.reset_at INTO v_count, v_reset
    FROM scm.pos_pin_attempts a WHERE a.staff_id = p_staff_id::uuid; -- $
  IF NOT FOUND OR v_reset <= now() THEN
    RETURN QUERY SELECT true, 0, p_max; -- $
    RETURN; -- $
  END IF; -- $
  IF v_count >= p_max THEN
    RETURN QUERY SELECT false, GREATEST(CEIL(EXTRACT(EPOCH FROM (v_reset - now())))::integer, 1), 0; -- $
  ELSE
    RETURN QUERY SELECT true, 0, (p_max - v_count); -- $
  END IF; -- $
END $function$;

CREATE OR REPLACE FUNCTION scm.pin_attempt_check(p_staff_id uuid, p_max integer)
 RETURNS TABLE(allowed boolean, retry_after integer, remaining integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE r pos_pin_attempts%ROWTYPE;
BEGIN
  SELECT * INTO r FROM pos_pin_attempts WHERE staff_id = p_staff_id;
  IF NOT FOUND OR r.reset_at <= NOW() THEN
    RETURN QUERY SELECT TRUE, 0, p_max;
  ELSIF r.count >= p_max THEN
    RETURN QUERY SELECT FALSE, CEIL(EXTRACT(EPOCH FROM (r.reset_at - NOW())))::INT, 0;
  ELSE
    RETURN QUERY SELECT TRUE, 0, (p_max - r.count);
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.pin_attempt_fail(p_staff_id text, p_window_seconds integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'pg_temp'
AS $function$
BEGIN
  INSERT INTO scm.pos_pin_attempts (staff_id, count, reset_at)
  VALUES (p_staff_id::uuid, 1, now() + make_interval(secs => p_window_seconds))
  ON CONFLICT (staff_id) DO UPDATE
    SET count = CASE WHEN scm.pos_pin_attempts.reset_at <= now()
                     THEN 1 ELSE scm.pos_pin_attempts.count + 1 END,
        reset_at = CASE WHEN scm.pos_pin_attempts.reset_at <= now()
                        THEN now() + make_interval(secs => p_window_seconds)
                        ELSE scm.pos_pin_attempts.reset_at END; -- $
END $function$;

CREATE OR REPLACE FUNCTION scm.pin_attempt_fail(p_staff_id uuid, p_window_seconds integer)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'scm', 'pg_temp'
AS $function$
  INSERT INTO pos_pin_attempts (staff_id, count, reset_at)
  VALUES (p_staff_id, 1, NOW() + make_interval(secs => p_window_seconds))
  ON CONFLICT (staff_id) DO UPDATE SET
    count    = CASE WHEN pos_pin_attempts.reset_at <= NOW() THEN 1
                    ELSE pos_pin_attempts.count + 1 END,
    reset_at = CASE WHEN pos_pin_attempts.reset_at <= NOW() THEN NOW() + make_interval(secs => p_window_seconds)
                    ELSE pos_pin_attempts.reset_at END;
$function$;

CREATE OR REPLACE FUNCTION scm.pin_attempt_reset(p_staff_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'pg_temp'
AS $function$
BEGIN
  DELETE FROM scm.pos_pin_attempts WHERE staff_id = p_staff_id::uuid; -- $
END $function$;

CREATE OR REPLACE FUNCTION scm.pin_attempt_reset(p_staff_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'scm', 'pg_temp'
AS $function$
  DELETE FROM pos_pin_attempts WHERE staff_id = p_staff_id;
$function$;

CREATE OR REPLACE FUNCTION scm.pos_sofa_combo_audit_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  RAISE EXCEPTION USING
    ERRCODE = '42501',
    MESSAGE = 'pos_sofa_combo_audit is append-only.';
END
$function$;

CREATE OR REPLACE FUNCTION scm.pos_sofa_combo_insert(p_company_id bigint, p_row jsonb, p_actor jsonb)
 RETURNS scm.pos_sofa_combos
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'public', 'pg_temp'
AS $function$
DECLARE
  v scm.pos_sofa_combos;
BEGIN
  IF p_company_id IS NULL THEN
    RAISE EXCEPTION 'pos_sofa_combo_insert: company_id is required';
  END IF;

  PERFORM set_config('scm.pos_sofa_combo_writer', 'pos', true);

  INSERT INTO scm.pos_sofa_combos
    (company_id, base_model, modules, tier, selling_prices_by_height, pwp_prices_by_height,
     default_free_gifts, label, effective_from, notes, created_by, created_by_name)
  VALUES
    (p_company_id,
     p_row ->> 'base_model',
     COALESCE(p_row -> 'modules', '[]'::jsonb),
     NULLIF(p_row ->> 'tier', ''),
     COALESCE(p_row -> 'selling_prices_by_height', '{}'::jsonb),
     COALESCE(p_row -> 'pwp_prices_by_height', '{}'::jsonb),
     COALESCE(p_row -> 'default_free_gifts', '[]'::jsonb),
     p_row ->> 'label',
     (p_row ->> 'effective_from')::date,
     p_row ->> 'notes',
     NULLIF(p_row ->> 'created_by', '')::uuid,
     p_actor ->> 'name')
  RETURNING * INTO v;

  INSERT INTO scm.pos_sofa_combo_audit
    (company_id, combo_id, action, actor_user_id, actor_name, actor_email, detail)
  VALUES
    (p_company_id, v.id, 'create',
     NULLIF(p_actor ->> 'user_id', '')::bigint, p_actor ->> 'name', p_actor ->> 'email',
     jsonb_build_object('base_model', v.base_model, 'modules', v.modules,
                        'selling_prices_by_height', v.selling_prices_by_height,
                        'effective_from', v.effective_from));

  PERFORM set_config('scm.pos_sofa_combo_writer', '', true);
  RETURN v;
END
$function$;

CREATE OR REPLACE FUNCTION scm.pos_sofa_combo_retire(p_company_id bigint, p_id uuid, p_actor jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'public', 'pg_temp'
AS $function$
DECLARE
  n integer;
BEGIN
  IF p_company_id IS NULL THEN
    RAISE EXCEPTION 'pos_sofa_combo_retire: company_id is required';
  END IF;

  PERFORM set_config('scm.pos_sofa_combo_writer', 'pos', true);

  UPDATE scm.pos_sofa_combos
     SET deleted_at = now(), updated_at = now()
   WHERE id = p_id
     AND company_id = p_company_id
     AND deleted_at IS NULL;
  GET DIAGNOSTICS n = ROW_COUNT;

  IF n > 0 THEN
    INSERT INTO scm.pos_sofa_combo_audit
      (company_id, combo_id, action, actor_user_id, actor_name, actor_email)
    VALUES
      (p_company_id, p_id, 'retire',
       NULLIF(p_actor ->> 'user_id', '')::bigint, p_actor ->> 'name', p_actor ->> 'email');
  END IF;

  PERFORM set_config('scm.pos_sofa_combo_writer', '', true);
  RETURN n > 0;
END
$function$;

CREATE OR REPLACE FUNCTION scm.pos_sofa_combos_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP IN ('DELETE', 'TRUNCATE') THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'pos_sofa_combos: 2990 POS combos are never deleted. Retire one from the 2990 POS (owner ruling 2026-09-26).';
  END IF;

  IF current_setting('scm.pos_sofa_combo_writer', true) IS DISTINCT FROM 'pos' THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'pos_sofa_combos: 2990 POS selling combos are written only by the 2990 POS. Houzs screens and scripts may not change them (owner ruling 2026-09-26).';
  END IF;

  IF TG_OP = 'UPDATE'
     AND (OLD.deleted_at IS NOT NULL
          OR NEW.deleted_at IS NULL
          OR (to_jsonb(NEW) - 'deleted_at' - 'updated_at')
             IS DISTINCT FROM (to_jsonb(OLD) - 'deleted_at' - 'updated_at')) THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'pos_sofa_combos: a combo is append-only. The only change allowed is retiring it.';
  END IF;

  RETURN NEW;
END
$function$;

