CREATE OR REPLACE FUNCTION scm.rebuild_mfg_so_delivery_lines(p_doc_no text, p_source_doc_no text, p_delivery_fee_sen bigint, p_rows jsonb, p_expect_state jsonb DEFAULT NULL::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_company_id bigint;
  v_state      jsonb;
BEGIN
  -- Serialize concurrent rebuilds of the SAME SO. hashtextextended gives a
  -- bigint key; the xact lock releases automatically at commit/rollback.
  PERFORM pg_advisory_xact_lock(hashtextextended('scm-so-delivery:' || p_doc_no, 0));

  /* 0. AGREE. Everything below derives from fee lines the CALLER read before
     the lock above existed for it. Re-read the operator-owned half here, under
     the lock, and refuse rather than overwrite a figure this derivation never
     saw. NULL means the caller claims no expectation (see the header). */
  IF p_expect_state IS NOT NULL THEN
    SELECT COALESCE(jsonb_object_agg(
             x.id::text,
             jsonb_build_array(
               x.item_code,
               COALESCE(x.qty, 0)::bigint,
               COALESCE(x.unit_price_sen, 0)::bigint,
               COALESCE(x.discount_sen, 0)::bigint)), '{}'::jsonb)
      INTO v_state
      FROM scm.mfg_sales_order_items x
     WHERE x.doc_no = p_doc_no
       AND x.item_code IN ('SVC-DELIVERY', 'SVC-DELIVERY-CROSS', 'SVC-DELIVERY-ADD')
       AND COALESCE(x.cancelled, false) = false;
    IF v_state IS DISTINCT FROM p_expect_state THEN
      RETURN false;
    END IF;
  END IF;

  SELECT company_id INTO v_company_id
    FROM scm.mfg_sales_orders
   WHERE doc_no = p_doc_no;
  -- Unknown SO: rebuild nothing rather than orphan lines onto a missing header.
  IF v_company_id IS NULL THEN
    RETURN true;
  END IF;

  -- 1. REUSE. Every incoming row that has a live counterpart of the same
  --    item_code updates it in place, so the row id — and any DO line pointing
  --    at it — survives the rebuild.
  WITH incoming AS (
    SELECT p.*, row_number() OVER (PARTITION BY p.item_code ORDER BY e.ord) AS seq
      FROM jsonb_array_elements(COALESCE(p_rows, '[]'::jsonb)) WITH ORDINALITY AS e(val, ord)
      CROSS JOIN LATERAL jsonb_populate_record(NULL::scm.mfg_sales_order_items, e.val) AS p
  ), live AS (
    SELECT x.id, x.item_code,
           row_number() OVER (PARTITION BY x.item_code ORDER BY x.id) AS seq
      FROM scm.mfg_sales_order_items x
     WHERE x.doc_no = p_doc_no
       AND x.item_code IN ('SVC-DELIVERY', 'SVC-DELIVERY-CROSS', 'SVC-DELIVERY-ADD')
       AND COALESCE(x.cancelled, false) = false
  )
  UPDATE scm.mfg_sales_order_items t
     SET line_no                       = i.line_no,
         line_date                     = i.line_date,
         debtor_name                   = i.debtor_name,
         item_group                    = i.item_group,
         description                   = i.description,
         description2                  = i.description2,
         remark                        = i.remark,
         uom                           = i.uom,
         qty                           = i.qty,
         unit_price_sen                = i.unit_price_sen,
         discount_sen                  = i.discount_sen,
         total_sen                     = i.total_sen,
         total_inc_sen                 = i.total_inc_sen,
         balance_sen                   = i.balance_sen,
         variants                      = i.variants,
         unit_cost_sen                 = i.unit_cost_sen,
         line_cost_sen                 = i.line_cost_sen,
         line_margin_sen               = i.line_margin_sen,
         divan_price_sen               = i.divan_price_sen,
         leg_price_sen                 = i.leg_price_sen,
         special_order_price_sen       = i.special_order_price_sen,
         custom_specials               = i.custom_specials,
         line_delivery_date            = i.line_delivery_date,
         line_delivery_date_overridden = i.line_delivery_date_overridden,
         warehouse_id                  = i.warehouse_id,
         branding                      = i.branding,
         venue                         = i.venue,
         stock_status                  = i.stock_status
    FROM live l
    JOIN incoming i ON i.item_code = l.item_code AND i.seq = l.seq
   WHERE t.id = l.id;

  -- 2. RETIRE. A fee component that no longer exists — and every cancelled
  --    SVC-DELIVERY* line, which never matches — goes, exactly as before. This
  --    is the one remaining path that can blank a DO link, and it should: the
  --    line it pointed at is genuinely gone.
  WITH incoming AS (
    SELECT p.item_code, row_number() OVER (PARTITION BY p.item_code ORDER BY e.ord) AS seq
      FROM jsonb_array_elements(COALESCE(p_rows, '[]'::jsonb)) WITH ORDINALITY AS e(val, ord)
      CROSS JOIN LATERAL jsonb_populate_record(NULL::scm.mfg_sales_order_items, e.val) AS p
  ), live AS (
    SELECT x.id, x.item_code,
           row_number() OVER (PARTITION BY x.item_code ORDER BY x.id) AS seq
      FROM scm.mfg_sales_order_items x
     WHERE x.doc_no = p_doc_no
       AND x.item_code IN ('SVC-DELIVERY', 'SVC-DELIVERY-CROSS', 'SVC-DELIVERY-ADD')
       AND COALESCE(x.cancelled, false) = false
  ), keep AS (
    SELECT l.id FROM live l JOIN incoming i ON i.item_code = l.item_code AND i.seq = l.seq
  )
  DELETE FROM scm.mfg_sales_order_items t
   WHERE t.doc_no = p_doc_no
     AND t.item_code IN ('SVC-DELIVERY', 'SVC-DELIVERY-CROSS', 'SVC-DELIVERY-ADD')
     AND NOT EXISTS (SELECT 1 FROM keep k WHERE k.id = t.id);

  -- 3. ADD. Only the components with no line to reuse. `live` is re-read after
  --    step 2, which removed only unmatched rows from the tail of each
  --    item_code group, so the surviving sequence numbers are the ones step 1
  --    matched on.
  WITH incoming AS (
    SELECT p.*, row_number() OVER (PARTITION BY p.item_code ORDER BY e.ord) AS seq
      FROM jsonb_array_elements(COALESCE(p_rows, '[]'::jsonb)) WITH ORDINALITY AS e(val, ord)
      CROSS JOIN LATERAL jsonb_populate_record(NULL::scm.mfg_sales_order_items, e.val) AS p
  ), live AS (
    SELECT x.id, x.item_code,
           row_number() OVER (PARTITION BY x.item_code ORDER BY x.id) AS seq
      FROM scm.mfg_sales_order_items x
     WHERE x.doc_no = p_doc_no
       AND x.item_code IN ('SVC-DELIVERY', 'SVC-DELIVERY-CROSS', 'SVC-DELIVERY-ADD')
       AND COALESCE(x.cancelled, false) = false
  )
  INSERT INTO scm.mfg_sales_order_items (
    company_id, doc_no, line_no, line_date, debtor_name, item_group, item_code,
    description, description2, remark, uom, qty,
    unit_price_sen, discount_sen, total_sen, total_inc_sen, balance_sen,
    variants, unit_cost_sen, line_cost_sen, line_margin_sen,
    divan_price_sen, leg_price_sen, special_order_price_sen, custom_specials,
    line_delivery_date, line_delivery_date_overridden, warehouse_id,
    branding, venue, stock_status
  )
  SELECT v_company_id, i.doc_no, i.line_no, i.line_date, i.debtor_name, i.item_group, i.item_code,
         i.description, i.description2, i.remark, i.uom, i.qty,
         i.unit_price_sen, i.discount_sen, i.total_sen, i.total_inc_sen, i.balance_sen,
         i.variants, i.unit_cost_sen, i.line_cost_sen, i.line_margin_sen,
         i.divan_price_sen, i.leg_price_sen, i.special_order_price_sen, i.custom_specials,
         i.line_delivery_date, i.line_delivery_date_overridden, i.warehouse_id,
         i.branding, i.venue, i.stock_status
    FROM incoming i
   WHERE NOT EXISTS (
     SELECT 1 FROM live l WHERE l.item_code = i.item_code AND l.seq = i.seq
   );

  UPDATE scm.mfg_sales_orders
     SET cross_category_source_doc_no = p_source_doc_no,
         delivery_fee_sen             = p_delivery_fee_sen,
         updated_at                   = now()
   WHERE doc_no = p_doc_no;

  RETURN true;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.rename_sofa_compartment(p_company_id bigint, p_from text, p_to text, p_apply boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_from      text := trim(coalesce(p_from, ''));
  v_to        text := trim(coalesce(p_to, ''));
  v_suffix    text;
  v_has_from  jsonb;
  v_longest   int;
  v_pool      jsonb;
  in_use      jsonb := '{}'::jsonb;
  in_use_n    bigint := 0;
  changes     jsonb := '{}'::jsonb;
  n           bigint;
  t           record;
  v_photo     boolean;
BEGIN
  IF p_company_id IS NULL THEN RAISE EXCEPTION 'company_required'; END IF;
  IF p_apply IS NULL THEN RAISE EXCEPTION 'apply_required'; END IF;
  IF v_from = '' OR v_to = '' THEN RAISE EXCEPTION 'empty_code'; END IF;
  IF v_from = v_to THEN RAISE EXCEPTION 'same_code'; END IF;
  -- parseCompartmentStructure (sofa-build.ts) grammar, with no whitespace at all.
  IF v_to !~ '^[^()[:space:]]+(\([^()[:space:]]*\))*$' THEN RAISE EXCEPTION 'invalid_code'; END IF;

  SELECT max(length(m.model_code)) INTO v_longest
    FROM product_models m
   WHERE m.company_id = p_company_id AND m.category::text = 'SOFA';
  IF coalesce(v_longest, 0) + 1 + length(v_to) > 30 THEN RAISE EXCEPTION 'code_too_long'; END IF;

  -- Taken in this company's current master pool, or in a future-dated one.
  FOR v_pool IN
    SELECT h.config->'sofaCompartments'
      FROM maintenance_config_history h
     WHERE h.company_id = p_company_id AND h.scope = 'master'
       AND (h.effective_from > CURRENT_DATE
            OR h.id = (SELECT h2.id FROM maintenance_config_history h2
                        WHERE h2.company_id = p_company_id AND h2.scope = 'master'
                          AND h2.effective_from <= CURRENT_DATE
                        ORDER BY h2.effective_from DESC, h2.created_at DESC LIMIT 1))
  LOOP
    IF coalesce(jsonb_path_exists(v_pool, '$.** ? (@ == $s)', jsonb_build_object('s', v_to)), false) THEN
      RAISE EXCEPTION 'code_exists';
    END IF;
  END LOOP;

  v_suffix := '-' || v_from;
  v_has_from := jsonb_build_object('s', v_from);

  -- ── In use? Every item-code column of this company ending in -<from> ──
  FOR t IN SELECT * FROM (VALUES
      ('mfg_products', 'code'),
      ('mfg_sales_order_items', 'item_code'),
      ('mfg_so_price_overrides', 'item_code'),
      ('delivery_order_items', 'item_code'),
      ('delivery_return_items', 'item_code'),
      ('sales_invoice_items', 'item_code'),
      ('consignment_sales_order_items', 'item_code'),
      ('consignment_delivery_order_items', 'item_code'),
      ('consignment_delivery_return_items', 'item_code'),
      ('purchase_order_items', 'item_code'),
      ('grn_items', 'item_code'),
      ('purchase_invoice_items', 'item_code'),
      ('purchase_return_items', 'item_code'),
      ('purchase_consignment_order_items', 'item_code'),
      ('purchase_consignment_receive_items', 'item_code'),
      ('purchase_consignment_return_items', 'item_code'),
      ('supplier_material_bindings', 'item_code'),
      ('pwp_codes', 'trigger_item_code'),
      ('pwp_codes', 'redeemed_item_code'),
      ('inventory_movements', 'item_code'),
      ('inventory_balances', 'item_code'),
      ('inventory_lots', 'item_code'),
      ('stock_transfer_lines', 'item_code'),
      ('stock_take_lines', 'item_code'),
      ('warehouse_rack_items', 'item_code')
    ) AS x(tbl, col)
  LOOP
    EXECUTE format('SELECT count(*) FROM scm.%I WHERE company_id = $1 AND right(%I, $2) = $3', t.tbl, t.col)
       INTO n USING p_company_id, length(v_suffix), v_suffix;
    in_use := in_use || jsonb_build_object(t.tbl || '.' || t.col, n);
    in_use_n := in_use_n + n;
  END LOOP;

  SELECT count(*) INTO n FROM product_compartments
   WHERE company_id = p_company_id AND compartment_id = v_from;
  in_use := in_use || jsonb_build_object('product_compartments.compartment_id', n);
  in_use_n := in_use_n + n;

  SELECT count(*) INTO n FROM pos_sofa_combos
   WHERE company_id = p_company_id
     AND coalesce(jsonb_path_exists(modules, '$.** ? (@ == $s)', v_has_from), false);
  in_use := in_use || jsonb_build_object('pos_sofa_combos.modules', n);
  in_use_n := in_use_n + n;

  -- No company_id on personal picks: a pick belongs to the company whose Model it is.
  SELECT count(*) INTO n FROM sofa_personal_quick_picks p
   WHERE p.base_model IN (SELECT m.model_code FROM product_models m WHERE m.company_id = p_company_id)
     AND coalesce(jsonb_path_exists(p.modules, '$.** ? (@ == $s)', v_has_from), false);
  in_use := in_use || jsonb_build_object('sofa_personal_quick_picks.modules', n);
  in_use_n := in_use_n + n;

  -- ── What a rename would change (same predicates as the writes below) ──
  SELECT count(*) INTO n FROM maintenance_config_history h
   WHERE h.company_id = p_company_id
     AND (coalesce(jsonb_path_exists(h.config->'sofaCompartments', '$.** ? (@ == $s)', v_has_from), false)
          OR (jsonb_typeof(h.config->'sofaCompartmentMeta') = 'object' AND (h.config->'sofaCompartmentMeta') ? v_from));
  changes := changes || jsonb_build_object('maintenance_config_history', n);

  SELECT count(*) INTO n FROM product_models m
   WHERE m.company_id = p_company_id
     AND coalesce(jsonb_path_exists(m.allowed_options->'compartments', '$.** ? (@ == $s)', v_has_from), false);
  changes := changes || jsonb_build_object('product_models', n);

  SELECT count(*) INTO n FROM sofa_combo_pricing s
   WHERE s.company_id = p_company_id
     AND coalesce(jsonb_path_exists(s.modules, '$.** ? (@ == $s)', v_has_from), false);
  changes := changes || jsonb_build_object('sofa_combo_pricing', n);

  SELECT count(*) INTO n FROM sofa_quick_picks q
   WHERE q.company_id = p_company_id
     AND coalesce(jsonb_path_exists(q.modules, '$.** ? (@ == $s)', v_has_from), false);
  changes := changes || jsonb_build_object('sofa_quick_picks', n);

  -- An uploaded photo lives under sofa-compartments/<code>/ and is only served
  -- for that code, so it cannot follow the rename.
  SELECT EXISTS (
    SELECT 1 FROM maintenance_config_history h
     WHERE h.company_id = p_company_id
       AND jsonb_typeof(h.config->'sofaCompartmentMeta') = 'object'
       AND coalesce(h.config->'sofaCompartmentMeta'->v_from->>'imageKey', '') LIKE 'sofa-compartments/%'
  ) INTO v_photo;

  IF NOT p_apply OR in_use_n > 0 THEN
    RETURN jsonb_build_object(
      'from', v_from, 'to', v_to, 'companyId', p_company_id,
      'applied', false,
      'refused', CASE WHEN in_use_n > 0 THEN 'in_use' ELSE NULL END,
      'inUse', in_use, 'inUseTotal', in_use_n,
      'changes', changes, 'photoCleared', v_photo);
  END IF;

  -- ── Apply: this company only ─────────────────────────────────────────
  UPDATE maintenance_config_history h
     SET config = CASE
           WHEN jsonb_typeof(c.cfg->'sofaCompartmentMeta') = 'object' AND (c.cfg->'sofaCompartmentMeta') ? v_from
           THEN jsonb_set(c.cfg, '{sofaCompartmentMeta}',
                  ((c.cfg->'sofaCompartmentMeta') - v_from)
                  || jsonb_build_object(v_to,
                       CASE WHEN jsonb_typeof(c.cfg->'sofaCompartmentMeta'->v_from) = 'object'
                             AND coalesce(c.cfg->'sofaCompartmentMeta'->v_from->>'imageKey', '') LIKE 'sofa-compartments/%'
                            THEN (c.cfg->'sofaCompartmentMeta'->v_from) - 'imageKey'
                            ELSE c.cfg->'sofaCompartmentMeta'->v_from END))
           ELSE c.cfg END
    FROM (SELECT h2.id,
                 CASE WHEN h2.config ? 'sofaCompartments'
                      THEN jsonb_set(h2.config, '{sofaCompartments}',
                             scm.jsonb_replace_string_value(h2.config->'sofaCompartments', v_from, v_to))
                      ELSE h2.config END AS cfg
            FROM maintenance_config_history h2
           WHERE h2.company_id = p_company_id
             AND (coalesce(jsonb_path_exists(h2.config->'sofaCompartments', '$.** ? (@ == $s)', v_has_from), false)
                  OR (jsonb_typeof(h2.config->'sofaCompartmentMeta') = 'object' AND (h2.config->'sofaCompartmentMeta') ? v_from))) c
   WHERE h.id = c.id AND h.company_id = p_company_id;

  UPDATE product_models m
     SET allowed_options = jsonb_set(m.allowed_options, '{compartments}',
           scm.jsonb_replace_string_value(m.allowed_options->'compartments', v_from, v_to))
   WHERE m.company_id = p_company_id
     AND coalesce(jsonb_path_exists(m.allowed_options->'compartments', '$.** ? (@ == $s)', v_has_from), false);

  UPDATE sofa_combo_pricing s
     SET modules = scm.jsonb_replace_string_value(s.modules, v_from, v_to)
   WHERE s.company_id = p_company_id
     AND coalesce(jsonb_path_exists(s.modules, '$.** ? (@ == $s)', v_has_from), false);

  UPDATE sofa_quick_picks q
     SET modules = scm.jsonb_replace_string_value(q.modules, v_from, v_to)
   WHERE q.company_id = p_company_id
     AND coalesce(jsonb_path_exists(q.modules, '$.** ? (@ == $s)', v_has_from), false);

  RETURN jsonb_build_object(
    'from', v_from, 'to', v_to, 'companyId', p_company_id,
    'applied', true, 'refused', NULL,
    'inUse', in_use, 'inUseTotal', in_use_n,
    'changes', changes, 'photoCleared', v_photo);
END;
$function$;

CREATE OR REPLACE FUNCTION scm.settle_api_paid_sen(p_id uuid, p_delta bigint)
 RETURNS TABLE(applied_sen bigint, new_paid_sen bigint, new_status text, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_old_paid   bigint;
  v_total      bigint;
  v_status     text;
  v_new_paid   bigint;
  v_new_status text;
BEGIN
  IF p_id IS NULL OR p_delta IS NULL OR p_delta = 0 THEN
    RETURN QUERY SELECT 0::bigint, NULL::bigint, NULL::text, 'no_delta'::text; RETURN;
  END IF;

  SELECT COALESCE(paid_sen, 0), COALESCE(total_sen, 0), status
    INTO v_old_paid, v_total, v_status
    FROM ap_invoices
   WHERE id = p_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT 0::bigint, NULL::bigint, NULL::text, 'not_found'::text; RETURN;
  END IF;

  IF upper(COALESCE(v_status, '')) IN ('DRAFT', 'CANCELLED') THEN
    RETURN QUERY SELECT 0::bigint, v_old_paid, v_status, 'not_live'::text; RETURN;
  END IF;

  IF p_delta > 0 THEN
    v_new_paid := GREATEST(v_old_paid, LEAST(v_total, v_old_paid + p_delta));
  ELSE
    v_new_paid := GREATEST(0, v_old_paid + p_delta);
  END IF;

  UPDATE ap_invoices
     SET paid_sen   = v_new_paid,
         status     = CASE
                        WHEN v_new_paid >= v_total THEN 'PAID'
                        WHEN v_new_paid > 0        THEN 'PARTIALLY_PAID'
                        ELSE                            'POSTED'
                      END,
         updated_at = now()
   WHERE id = p_id
  RETURNING status INTO v_new_status;

  RETURN QUERY SELECT (v_new_paid - v_old_paid), v_new_paid, v_new_status, NULL::text;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.settle_pi_paid_sen(p_pi_id uuid, p_delta bigint)
 RETURNS TABLE(applied_sen bigint, new_paid_sen bigint, new_status text, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_old_paid   bigint;
  v_total      bigint;
  v_status     text;
  v_new_paid   bigint;
  v_new_status text;
BEGIN
  IF p_pi_id IS NULL OR p_delta IS NULL OR p_delta = 0 THEN
    RETURN QUERY SELECT 0::bigint, NULL::bigint, NULL::text, 'no_delta'::text; RETURN;
  END IF;

  -- The lock that makes this safe. A second settle against this PI waits here
  -- and then reads the row THIS transaction committed, not the one it started
  -- with, so its clamp is computed against the true remaining balance.
  SELECT COALESCE(paid_sen, 0), COALESCE(total_sen, 0), status::text
    INTO v_old_paid, v_total, v_status
    FROM purchase_invoices
   WHERE id = p_pi_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT 0::bigint, NULL::bigint, NULL::text, 'not_found'::text; RETURN;
  END IF;

  -- A DRAFT or CANCELLED invoice is not a live liability — unchanged behaviour.
  IF upper(COALESCE(v_status, '')) IN ('DRAFT', 'CANCELLED') THEN
    RETURN QUERY SELECT 0::bigint, v_old_paid, v_status, 'not_live'::text; RETURN;
  END IF;

  IF p_delta > 0 THEN
    -- LEAST caps the over-payment. The outer GREATEST stops a PI that is
    -- ALREADY over total (legacy data) from being silently pulled DOWN to
    -- total by an unrelated settle — this function only ever moves paid_sen
    -- in the direction of the delta it was given.
    v_new_paid := GREATEST(v_old_paid, LEAST(v_total, v_old_paid + p_delta));
  ELSE
    v_new_paid := GREATEST(0, v_old_paid + p_delta);
  END IF;

  -- The status is an ENUM. Each branch is typed as one, so the CASE resolves to
  -- the column's own type and the assignment needs no cast that does not exist.
  UPDATE purchase_invoices
     SET paid_sen   = v_new_paid,
         status     = CASE
                        WHEN v_new_paid >= v_total THEN 'PAID'::scm.purchase_invoice_status
                        WHEN v_new_paid > 0        THEN 'PARTIALLY_PAID'::scm.purchase_invoice_status
                        ELSE                            'POSTED'::scm.purchase_invoice_status
                      END,
         updated_at = now()
   WHERE id = p_pi_id
  RETURNING status::text INTO v_new_status;

  RETURN QUERY SELECT (v_new_paid - v_old_paid), v_new_paid, v_new_status, NULL::text;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.sync_user_to_staff()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_id       uuid;
  v_active   boolean;
  v_name     text;
  v_initials text;
  v_code     text;
  v_try      integer := 0;
BEGIN
  v_id     := md5('houzs-user:' || NEW.id::text)::uuid;
  -- "Active" = not soft-deleted. 'invited' users (never logged in) still count,
  -- mirroring 0060, so a newly-invited salesperson is pickable immediately.
  v_active := (NEW.status <> 'disabled');
  v_name   := COALESCE(NULLIF(btrim(NEW.name), ''), NEW.email, 'User ' || NEW.id::text);
  -- Initials: first char of up to the first two whitespace-split name words,
  -- uppercased; fall back to the first two chars of the resolved name.
  SELECT upper(COALESCE(NULLIF(string_agg(left(w, 1), '' ORDER BY ord), ''), left(v_name, 2)))
    INTO v_initials
    FROM (
      SELECT w, ord
        FROM regexp_split_to_table(v_name, '\s+') WITH ORDINALITY AS t(w, ord)
       WHERE w <> ''
       ORDER BY ord
       LIMIT 2
    ) parts;

  UPDATE scm.staff
     SET name = v_name, active = v_active, initials = v_initials
   WHERE id = v_id OR user_id = NEW.id;
  IF FOUND THEN
    RETURN NEW;
  END IF;

  -- No linked staff row. Switching OFF a user who has nothing to switch off is
  -- a no-op -- and it must be, because the INSERT below is the only part of
  -- this trigger that can raise, and a failure here aborts the users UPDATE
  -- that fired it.
  IF NOT v_active THEN
    RETURN NEW;
  END IF;

  -- staff_code is UNIQUE, and ON CONFLICT can only arbitrate on the primary
  -- key here, so a code held by another row would raise duplicate key. Probe
  -- for a free one; the preferred code is tried first, so existing behaviour is
  -- unchanged whenever it is available.
  v_code := 'EMP-' || lpad(NEW.id::text, 4, '0');
  WHILE EXISTS (SELECT 1 FROM scm.staff WHERE staff_code = v_code) LOOP
    v_try := v_try + 1;
    EXIT WHEN v_try > 50;
    v_code := 'EMP-' || lpad(NEW.id::text, 4, '0') || '-' || v_try::text;
  END LOOP;

  INSERT INTO scm.staff (id, user_id, staff_code, name, role, initials, color, active)
  VALUES (
    v_id,
    NEW.id,
    v_code,
    v_name,
    'sales'::scm.staff_role,
    v_initials,
    -- Deterministic hex colour from the id so a person's chip is stable.
    '#' || substr(md5('houzs-user:' || NEW.id::text), 1, 6),
    v_active
  )
  ON CONFLICT (id) DO UPDATE
    SET name = EXCLUDED.name, active = EXCLUDED.active,
        initials = EXCLUDED.initials, user_id = EXCLUDED.user_id;

  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION scm.sync_user_to_tms()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  pos text;
  is_driver boolean;
  is_helper boolean;
  v_company bigint;
BEGIN
  -- "Not disabled" (active OR invited) — field drivers/helpers are invited staff
  -- who never log into the ERP, so they stay status='invited' forever; only a
  -- soft-deleted user (status='disabled') is excluded.
  SELECT lower(p.name) INTO pos FROM public.positions p WHERE p.id = NEW.position_id;
  is_driver := (NEW.status <> 'disabled' AND pos = 'driver');
  is_helper := (NEW.status <> 'disabled' AND (pos IN ('helper', 'storekeeper', 'storekeeper supervisor') OR pos LIKE 'warehouse crew%'));

  SELECT id INTO v_company FROM public.companies WHERE code = 'HOUZS';
  v_company := coalesce(v_company, 1);

  -- DRIVER module
  IF is_driver THEN
    UPDATE scm.drivers
      SET name = NEW.name, phone = coalesce(NEW.phone, ''),
          ic_number = NEW.ic_number, active = true
      WHERE user_id = NEW.id;
    IF NOT FOUND THEN
      INSERT INTO scm.drivers (user_id, driver_code, name, phone, ic_number, in_house, active, company_id)
      VALUES (NEW.id, 'DRV-' || lpad(nextval('scm.driver_code_seq')::text, 3, '0'),
              NEW.name, coalesce(NEW.phone, ''), NEW.ic_number, true, true, v_company);
    END IF;
  ELSE
    UPDATE scm.drivers SET active = false WHERE user_id = NEW.id AND active;
  END IF;

  -- HELPER module (Helper + Storekeeper + Storekeeper Supervisor + Warehouse Crew *)
  IF is_helper THEN
    UPDATE scm.helpers
      SET name = NEW.name, contact = NEW.phone,
          ic_number = NEW.ic_number, active = true
      WHERE user_id = NEW.id;
    IF NOT FOUND THEN
      INSERT INTO scm.helpers (user_id, helper_code, name, contact, ic_number, in_house, active, company_id)
      VALUES (NEW.id, 'HLP-' || lpad(nextval('scm.helper_code_seq')::text, 3, '0'),
              NEW.name, NEW.phone, NEW.ic_number, true, true, v_company);
    END IF;
  ELSE
    UPDATE scm.helpers SET active = false WHERE user_id = NEW.id AND active;
  END IF;

  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION scm.upsert_customer_by_name_phone(p_name text, p_phone text, p_email text DEFAULT NULL::text, p_company_id bigint DEFAULT NULL::bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_id         uuid;
  v_company_id bigint := COALESCE(p_company_id, (SELECT id FROM public.companies WHERE code = 'HOUZS'));
  v_alpha      text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  v_code       text;
  i            int;
BEGIN
  IF p_name IS NULL OR btrim(p_name) = '' OR p_phone IS NULL OR btrim(p_phone) = '' THEN
    RAISE EXCEPTION 'upsert_customer_by_name_phone: name and phone are both required';
  END IF;

  SELECT id INTO v_id FROM scm.customers
    WHERE company_id = v_company_id
      AND lower(btrim(name)) = lower(btrim(p_name))
      AND phone = p_phone
    LIMIT 1;
  IF FOUND THEN
    UPDATE scm.customers SET last_seen_at = now() WHERE id = v_id;
    RETURN v_id;
  END IF;

  LOOP
    v_code := '2990S-';
    FOR i IN 1..8 LOOP
      v_code := v_code || substr(v_alpha, 1 + floor(random() * length(v_alpha))::int, 1);
    END LOOP;
    BEGIN
      INSERT INTO scm.customers (name, phone, email, customer_code, company_id)
      VALUES (btrim(p_name), p_phone, NULLIF(btrim(coalesce(p_email, '')), ''), v_code, v_company_id)
      RETURNING id INTO v_id;
      RETURN v_id;
    EXCEPTION WHEN unique_violation THEN
      SELECT id INTO v_id FROM scm.customers
        WHERE company_id = v_company_id
          AND lower(btrim(name)) = lower(btrim(p_name))
          AND phone = p_phone
        LIMIT 1;
      IF FOUND THEN
        UPDATE scm.customers SET last_seen_at = now() WHERE id = v_id;
        RETURN v_id;
      END IF;
    END;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.upsert_customer_by_name_phone(p_name text, p_phone text, p_email text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'pg_temp'
AS $function$
DECLARE
  v_id    uuid;
  v_alpha text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';  -- 31 chars, no 0/O/1/I/L
  v_code  text;
  i       int;
BEGIN
  IF p_name IS NULL OR btrim(p_name) = '' OR p_phone IS NULL OR btrim(p_phone) = '' THEN
    RAISE EXCEPTION 'upsert_customer_by_name_phone: name and phone are both required';
  END IF;

  SELECT id INTO v_id FROM customers
    WHERE lower(btrim(name)) = lower(btrim(p_name)) AND phone = p_phone
    LIMIT 1;
  IF FOUND THEN
    UPDATE customers SET last_seen_at = now() WHERE id = v_id;
    RETURN v_id;
  END IF;

  LOOP
    v_code := '2990S-';
    FOR i IN 1..8 LOOP
      v_code := v_code || substr(v_alpha, 1 + floor(random() * length(v_alpha))::int, 1);
    END LOOP;
    BEGIN
      INSERT INTO customers (name, phone, email, customer_code)
      VALUES (btrim(p_name), p_phone, NULLIF(btrim(coalesce(p_email, '')), ''), v_code)
      RETURNING id INTO v_id;
      RETURN v_id;
    EXCEPTION WHEN unique_violation THEN
      SELECT id INTO v_id FROM customers
        WHERE lower(btrim(name)) = lower(btrim(p_name)) AND phone = p_phone
        LIMIT 1;
      IF FOUND THEN
        UPDATE customers SET last_seen_at = now() WHERE id = v_id;
        RETURN v_id;
      END IF;
    END;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION scm.vp_build_catalogue(p_company_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'scm', 'public'
AS $function$
  SELECT jsonb_build_object(
           'companyId', p_company_id,
           'full', true,
           -- SKU Master. Inactive SKUs travel too: status says so.
           'products', COALESCE((
             SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                      'id', p.id,
                      'code', p.code,
                      'name', p.name,
                      'description', p.description,
                      'category', p.category,
                      'model_id', p.model_id,
                      'base_model', p.base_model,
                      'size_code', p.size_code,
                      'size_label', p.size_label,
                      'branding', p.branding,
                      'barcode', p.barcode,
                      'fabric_color', p.fabric_color,
                      'status', p.status,
                      'updated_at', p.updated_at))
                    ORDER BY p.id COLLATE "C")
               FROM scm.mfg_products p
              WHERE p.company_id = p_company_id), '[]'::jsonb),
           -- Modular. allowed_options is added after jsonb_strip_nulls so it
           -- arrives as stored.
           'models', COALESCE((
             SELECT jsonb_agg(
                      jsonb_strip_nulls(jsonb_build_object(
                        'id', m.id,
                        'model_code', m.model_code,
                        'name', m.name,
                        'category', m.category,
                        'branding', m.branding,
                        'description', m.description,
                        'active', m.active,
                        'updated_at', m.updated_at))
                      || CASE WHEN m.allowed_options IS NULL THEN '{}'::jsonb
                              ELSE jsonb_build_object('allowed_options', scm.vp_strip_money_keys(m.allowed_options))
                         END
                      ORDER BY m.id)
               FROM scm.product_models m
              WHERE m.company_id = p_company_id), '[]'::jsonb),
           -- No selling_price_sen, cost_price_sen or option_groups.
           'specials', COALESCE((
             SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                      'id', s.id,
                      'code', s.code,
                      'label', s.label,
                      'categories', to_jsonb(s.categories),
                      'active', s.active,
                      'sort_order', s.sort_order))
                    ORDER BY s.id)
               FROM scm.special_addons s
              WHERE s.company_id = p_company_id), '[]'::jsonb),
           -- The PRICE_n tiers are labels the portal prices by; price_sen,
           -- stock, usage and supplier columns stay here.
           'fabrics', COALESCE((
             SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                      'id', f.id,
                      'fabric_code', f.fabric_code,
                      'fabric_description', f.fabric_description,
                      'fabric_category', f.fabric_category,
                      'series', f.series,
                      'sofa_price_tier', f.sofa_price_tier,
                      'bedframe_price_tier', f.bedframe_price_tier,
                      'price_tier', f.price_tier,
                      'is_active', f.is_active))
                    ORDER BY f.id COLLATE "C")
               FROM scm.fabric_trackings f
              WHERE f.company_id = p_company_id), '[]'::jsonb),
           -- Master rows only (no customer, no supplier), soft-deleted ones
           -- included so the portal can retire them. heights = the keys of
           -- the cost grid, never its values.
           'combos', COALESCE((
             SELECT jsonb_agg(
                      jsonb_strip_nulls(jsonb_build_object(
                        'id', c.id,
                        'base_model', c.base_model,
                        'tier', c.tier,
                        'label', c.label,
                        'effective_from', c.effective_from,
                        'created_at', c.created_at,
                        'deleted_at', c.deleted_at,
                        'heights', COALESCE((
                          SELECT jsonb_agg(h ORDER BY h COLLATE "C")
                            FROM jsonb_object_keys(CASE WHEN jsonb_typeof(c.prices_by_height) = 'object'
                                                        THEN c.prices_by_height ELSE '{}'::jsonb END) AS h), '[]'::jsonb)))
                      || CASE WHEN c.modules IS NULL THEN '{}'::jsonb
                              ELSE jsonb_build_object('modules', scm.vp_strip_money_keys(c.modules))
                         END
                      ORDER BY c.id)
               FROM scm.sofa_combo_pricing c
              WHERE c.company_id = p_company_id
                AND c.customer_id IS NULL
                AND c.supplier_id IS NULL), '[]'::jsonb))
         -- Maintenance: the six Bedframe / Sofa pools of the effective master
         -- row. Absent when the company has none, so the portal leaves its
         -- copy alone rather than emptying it.
         || COALESCE((
              SELECT jsonb_build_object('maintenance', jsonb_build_object(
                       'effective_from', h.effective_from,
                       'pools', COALESCE((
                         SELECT jsonb_object_agg(k.key, COALESCE((
                                  SELECT jsonb_agg(
                                           CASE jsonb_typeof(e.entry)
                                             WHEN 'string' THEN e.entry
                                             ELSE jsonb_build_object(
                                                    'value', e.entry ->> 'value',
                                                    'active', (e.entry -> 'active') IS DISTINCT FROM 'false'::jsonb)
                                           END
                                           ORDER BY e.ord)
                                    FROM jsonb_array_elements(h.config -> k.key) WITH ORDINALITY AS e(entry, ord)
                                   WHERE jsonb_typeof(e.entry) = 'string'
                                      OR (jsonb_typeof(e.entry) = 'object'
                                          AND jsonb_typeof(e.entry -> 'value') IN ('string', 'number'))), '[]'::jsonb))
                           FROM unnest(ARRAY['divanHeights', 'totalHeights', 'gaps',
                                             'legHeights', 'sofaSizes', 'sofaLegHeights']) AS k(key)
                          WHERE jsonb_typeof(h.config -> k.key) = 'array'), '{}'::jsonb)))
                FROM scm.maintenance_config_history h
               WHERE h.company_id = p_company_id
                 AND h.scope = 'master'
                 AND h.effective_from <= (now() AT TIME ZONE 'Asia/Kuala_Lumpur')::date
               ORDER BY h.effective_from DESC, h.created_at DESC, h.id COLLATE "C" DESC
               LIMIT 1), '{}'::jsonb)
$function$;

CREATE OR REPLACE FUNCTION scm.vp_build_payloads(p_doc_nos text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'scm', 'public'
AS $function$
DECLARE
  out_rows jsonb := '[]'::jsonb;
  dn       text;
  hdr      jsonb;
  sp       jsonb;
BEGIN
  FOREACH dn IN ARRAY COALESCE(p_doc_nos, ARRAY[]::text[])
  LOOP
    /* The header comes from the VIEW, never the base table: paid_total_sen and
       balance_sen_live are computed there and the portal's deposit gate reads
       balance_sen_live first. Customer PII and the two whole-image base64
       columns are removed before the row ever leaves the database. */
    SELECT to_jsonb(v) - ARRAY[
             'phone', 'email',
             'address1', 'address2', 'address3', 'address4',
             'city', 'postcode',
             'ship_to_address', 'bill_to_address', 'install_to_address',
             'emergency_contact_name', 'emergency_contact_phone',
             'emergency_contact_relationship',
             'customer_po_image_b64', 'signature_b64',
             'note', 'remark2', 'remark3', 'remark4',
             /* The PAYMENT ARTEFACTS, added after reading what the payload
                actually carries rather than what the contract remembered to
                name. `approval_code` is a card/terminal authorisation code and
                the other three are pointers to payment-slip and receipt IMAGES
                — customer bank documents. None is a commission input, the
                portal's own field list (contract §3) reads none of them, and
                the portal answers 200 for anything it can still read, so
                removing them cannot break the receiver. Minimum privilege is
                the default here (CLAUDE.md rule 5), and this file becomes
                immutable the moment it is applied. */
             'approval_code', 'slip_key', 'slip_image_key', 'receipt_image_key']
      INTO hdr
      FROM scm.mfg_sales_orders_with_payment_totals v
     WHERE v.doc_no = dn;

    IF hdr IS NULL THEN
      /* The document is gone. The portal excludes it as DELETED; it does not
         guess, and neither do we. */
      out_rows := out_rows || jsonb_build_object(
        'docNo', dn, 'deleted', true, 'snapshotAt', now());
      CONTINUE;
    END IF;

    /* The person behind salesperson_id. The portal matches this to its own
       staff roster ONCE and remembers the pick, so id is the durable key and
       name is only the display and the fallback match. */
    SELECT jsonb_build_object(
             'id', s.id, 'name', s.name,
             'staff_code', s.staff_code, 'user_id', s.user_id)
      INTO sp
      FROM scm.staff s
     WHERE s.id = (hdr ->> 'salesperson_id')::uuid;

    out_rows := out_rows || jsonb_build_object(
      'docNo', dn,
      'snapshotAt', now(),
      'deleted', false,
      'header', hdr,
      'items', COALESCE((
        SELECT jsonb_agg(
                 /* Every column as before except `variants`, which is cut to
                    the option keys the portal parses a line by. Anything else
                    in it (extraAddonAmountRM, remark, extraAddonNote, ...) is
                    money or free text and stays here; an allowlisted key whose
                    value is an object is dropped, and an array keeps only its
                    strings, so nothing can hide inside one. */
                 (to_jsonb(i) - 'variants')
                 || COALESCE((
                      SELECT jsonb_build_object('variants', jsonb_object_agg(k.key,
                               CASE WHEN jsonb_typeof(i.variants -> k.key) = 'array'
                                    THEN jsonb_path_query_array(i.variants -> k.key, '$[*] ? (@.type() == "string")')
                                    ELSE i.variants -> k.key
                               END))
                        FROM unnest(ARRAY['fabricCode', 'seatHeight', 'legHeight', 'divanHeight',
                                          'gap', 'totalHeight', 'size', 'specials']) AS k(key)
                       WHERE jsonb_typeof(i.variants) = 'object'
                         AND jsonb_typeof(i.variants -> k.key) IN ('string', 'number', 'null', 'array')
                      HAVING count(*) > 0), '{}'::jsonb)
                 ORDER BY i.line_no NULLS LAST, i.created_at)
          FROM scm.mfg_sales_order_items i
         WHERE i.doc_no = dn), '[]'::jsonb),
      'payments', COALESCE((
        SELECT jsonb_agg(to_jsonb(p) ORDER BY p.paid_at, p.created_at)
          FROM scm.mfg_sales_order_payments p
         WHERE p.so_doc_no = dn), '[]'::jsonb),
      'salesperson', sp,
      /* The fair the salesperson picked (the fair picker, 2026-09-13): the
         brand booth's project, and the order's own verdict and day. Named
         keys only, so a project column added later cannot ride along. Read
         from the BASE table: the header view's column list predates
         project_id. NULL when the order has no project. */
      'fair', (
        SELECT jsonb_build_object(
                 'projectId', p.id,
                 'code', p.code,
                 'name', p.name,
                 'venue', p.venue,
                 'organizer', p.organizer,
                 'brand', p.brand,
                 'startDate', p.start_date,
                 'endDate', p.end_date,
                 'status', p.status,
                 'eventType', et.slug,
                 'match', so.fair_match,
                 'fairDate', so.fair_date)
          FROM scm.mfg_sales_orders so
          JOIN public.projects p ON p.id = so.project_id
          LEFT JOIN public.project_event_types et ON et.id = p.event_type_id
         WHERE so.doc_no = dn),
      /* Which brand the bill is FOR when its products name none (20260927T2100):
         the salesperson's answer to the order form's question, for the portal
         only -- `branding` in the header is untouched by it. Read from the
         BASE table like `fair`. NULL when never asked, or skipped. */
      'vpBrand', (
        SELECT so.vp_brand
          FROM scm.mfg_sales_orders so
         WHERE so.doc_no = dn));
  END LOOP;

  RETURN out_rows;
END
$function$;

CREATE OR REPLACE FUNCTION scm.vp_catalogue_digest(p_company_id bigint)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'scm', 'public'
AS $function$
  SELECT md5(scm.vp_build_catalogue(p_company_id)::text)
$function$;

CREATE OR REPLACE FUNCTION scm.vp_catalogue_mark_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'public'
AS $function$
BEGIN
  INSERT INTO scm.venture_portal_catalogue_changes (source) VALUES (TG_TABLE_NAME);
  RETURN NULL;
END
$function$;

CREATE OR REPLACE FUNCTION scm.vp_catalogue_snapshot(p_company_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'scm', 'public'
AS $function$
DECLARE
  body jsonb := scm.vp_build_catalogue(p_company_id);
BEGIN
  RETURN jsonb_build_object('digest', md5(body::text), 'body', body);
END
$function$;

CREATE OR REPLACE FUNCTION scm.vp_requeue_undelivered(p_companies bigint[], p_since date, p_include_failed boolean)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'scm', 'public'
AS $function$
DECLARE
  n integer;
BEGIN
  INSERT INTO scm.venture_portal_outbox (doc_no, op)
  SELECT so.doc_no, 'RECONCILE'
    FROM scm.mfg_sales_orders so
   WHERE (p_companies IS NULL OR so.company_id = ANY (p_companies))
     AND (p_since IS NULL OR so.so_date >= p_since)
     AND NOT EXISTS (SELECT 1 FROM scm.venture_portal_outbox o
                      WHERE o.doc_no = so.doc_no AND o.status = 'sent')
     AND NOT EXISTS (SELECT 1 FROM scm.venture_portal_outbox o
                      WHERE o.doc_no = so.doc_no AND o.status = 'pending')
     AND (p_include_failed
          OR NOT EXISTS (SELECT 1 FROM scm.venture_portal_outbox o
                          WHERE o.doc_no = so.doc_no AND o.status = 'failed'))
  ON CONFLICT (doc_no) WHERE status = 'pending' DO NOTHING;

  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END
$function$;

CREATE OR REPLACE FUNCTION scm.vp_strip_money_keys(p_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'scm', 'public'
AS $function$
BEGIN
  IF p_value IS NULL OR NOT jsonb_path_exists(p_value,
       'lax $.** ? (@.type() == "object").keyvalue() ? (@.key like_regex "price|cost|amount|surcharge|discount|margin|_sen$" flag "i" || @.key like_regex "(Sen|RM)$")') THEN
    RETURN p_value;
  END IF;

  IF jsonb_typeof(p_value) = 'object' THEN
    RETURN COALESCE((
      SELECT jsonb_object_agg(e.key, scm.vp_strip_money_keys(e.value))
        FROM jsonb_each(p_value) AS e
       WHERE NOT (e.key ~* '(price|cost|amount|surcharge|discount|margin|_sen$)'
                  OR e.key ~ '(Sen|RM)$')), '{}'::jsonb);
  END IF;

  -- An array with an offending object somewhere inside it.
  RETURN (
    SELECT jsonb_agg(scm.vp_strip_money_keys(e.value) ORDER BY e.ord)
      FROM jsonb_array_elements(p_value) WITH ORDINALITY AS e(value, ord));
END
$function$;

CREATE OR REPLACE FUNCTION scm.warehouse_sync_is_showroom()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.is_showroom := COALESCE(NEW.type = 'showroom', false);
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION scm.warehouses_canonicalize_venue_name()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.venue_name := scm.canonicalize_venue(NEW.venue_name);
  RETURN NEW;
END $function$;

create view scm."acc_acquirers" as
 SELECT l.company_id,
    g.code,
    g.display_name,
    l.transit_account_code,
    l.fee_account_code,
    l.bank_account_code,
    g.statement_format,
    g.has_unique_ref,
    g.fee_method,
    g.date_tolerance_days,
    g.column_map,
    g.total_net_label,
    g.summary_totals,
    g.dates_have_no_year,
    (g.is_active AND l.is_active) AS is_active
   FROM (scm.acc_company_acquirers l
     JOIN scm.acc_acquirer_config g ON ((g.code = l.acquirer_code)));

create view scm."inventory_balances" as
 SELECT warehouse_id,
    item_code,
    variant_key,
    max(product_name) AS product_name,
    sum(
        CASE
            WHEN (movement_type = 'IN'::scm.inventory_movement_type) THEN qty
            WHEN (movement_type = 'OUT'::scm.inventory_movement_type) THEN (- qty)
            WHEN (movement_type = 'ADJUSTMENT'::scm.inventory_movement_type) THEN qty
            WHEN (movement_type = 'TRANSFER'::scm.inventory_movement_type) THEN qty
            ELSE 0
        END) AS qty,
    max(created_at) AS last_movement_at,
    company_id
   FROM scm.inventory_movements
  GROUP BY warehouse_id, item_code, variant_key, company_id;

create view scm."mfg_sales_orders_with_payment_totals" as
 SELECT so.doc_no,
    so.transfer_to,
    so.so_date,
    so.branding,
    so.debtor_code,
    so.debtor_name,
    so.agent,
    so.sales_location,
    so.ref,
    so.venue,
    so.venue_id,
    so.address1,
    so.address2,
    so.address3,
    so.address4,
    so.phone,
    so.mattress_sofa_sen,
    so.bedframe_sen,
    so.accessories_sen,
    so.others_sen,
    so.mattress_sofa_cost_sen,
    so.bedframe_cost_sen,
    so.accessories_cost_sen,
    so.others_cost_sen,
    so.service_sen,
    so.service_cost_sen,
    so.local_total_sen,
    so.balance_sen,
    so.total_cost_sen,
    so.total_revenue_sen,
    so.total_margin_sen,
    so.margin_pct_basis,
    so.line_count,
    so.fabric_tier_addon_sen,
    so.delivery_fee_sen,
    so.cross_category_source_doc_no,
    so.currency,
    so.status,
    so.remark2,
    so.remark3,
    so.remark4,
    so.note,
    so.proceeded_at,
    so.sales_exemption_expiry,
    so.customer_id,
    so.customer_state,
    so.customer_country,
    so.customer_po_image_b64,
    so.customer_so_no,
    so.hub_id,
    so.hub_name,
    so.customer_delivery_date,
    so.processing_date,
    so.linked_do_doc_no,
    so.ship_to_address,
    so.bill_to_address,
    so.install_to_address,
    so.subtotal_sen,
    so.overdue,
    so.email,
    so.customer_type,
    so.salesperson_id,
    so.city,
    so.postcode,
    so.building_type,
    so.emergency_contact_name,
    so.emergency_contact_phone,
    so.emergency_contact_relationship,
    so.target_date,
    so.signature_b64,
    so.slip_key,
    so.slip_state,
    so.payment_method,
    so.installment_months,
    so.merchant_provider,
    so.approval_code,
    so.payment_date,
    so.deposit_sen,
    so.paid_sen,
    so.created_at,
    so.created_by,
    so.updated_at,
    so.priority_rank,
    so.priority_set_at,
    so.priority_set_by,
    so.priority_reason,
    so.allocation_warehouse_id,
    so.slip_image_key,
    so.receipt_image_key,
    so.delivery_state,
    so.possession_date,
    so.house_type,
    so.replacement_disposal,
    so.referral,
    so.amend_date_from_customer,
    so.amended_delivery_date,
    so.amend_reason,
    so.revision,
    so.company_id,
    COALESCE(p.paid_total, (0)::bigint) AS paid_total_sen,
    (so.local_total_sen - COALESCE(p.paid_total, (0)::bigint)) AS balance_sen_live,
    so.on_hold,
    so.hold_reason,
    so.held_at,
    so.held_by,
    so.collaborator_staff_ids,
    so.access_staff_ids,
    so.open_to_all
   FROM (scm.mfg_sales_orders so
     LEFT JOIN ( SELECT mfg_sales_order_payments.so_doc_no,
            sum(mfg_sales_order_payments.amount_sen) AS paid_total
           FROM scm.mfg_sales_order_payments
          GROUP BY mfg_sales_order_payments.so_doc_no) p ON ((p.so_doc_no = so.doc_no)));

create view scm."suppliers_with_derived_category" as
 SELECT id,
    code,
    name,
    whatsapp_number,
    email,
    contact_person,
    phone,
    address,
    state,
    country,
    payment_terms,
    status,
    rating,
    notes,
    supplier_type,
    category,
    tin_number,
    business_reg_no,
    postcode,
    area,
    mobile,
    fax,
    website,
    attention,
    business_nature,
    currency,
    statement_type,
    aging_basis,
    credit_limit_sen,
    created_at,
    updated_at,
    registration_no,
    nature_of_business,
    exemption_no,
    phone2,
    company_id,
    ( SELECT
                CASE
                    WHEN (count(DISTINCT mp.category) = 0) THEN NULL::text
                    WHEN (count(DISTINCT mp.category) = 1) THEN max((mp.category)::text)
                    ELSE 'MIXED'::text
                END AS "case"
           FROM (scm.supplier_material_bindings smb
             LEFT JOIN scm.mfg_products mp ON (((mp.code = smb.item_code) AND (smb.material_kind = 'mfg_product'::scm.material_kind))))
          WHERE (smb.supplier_id = s.id)) AS derived_category
   FROM scm.suppliers s;

create view scm."v_account_balances" as
 SELECT a.account_code,
    a.account_name,
    a.account_type,
    COALESCE(sum(l.debit_sen), (0)::bigint) AS total_debit_sen,
    COALESCE(sum(l.credit_sen), (0)::bigint) AS total_credit_sen,
        CASE
            WHEN (a.account_type = ANY (ARRAY['ASSET'::text, 'EXPENSE'::text])) THEN (COALESCE(sum(l.debit_sen), (0)::bigint) - COALESCE(sum(l.credit_sen), (0)::bigint))
            ELSE (COALESCE(sum(l.credit_sen), (0)::bigint) - COALESCE(sum(l.debit_sen), (0)::bigint))
        END AS balance_sen,
    a.company_id
   FROM (scm.accounts a
     LEFT JOIN ( SELECT l_1.account_code,
            l_1.company_id,
            l_1.debit_sen,
            l_1.credit_sen
           FROM (scm.journal_entry_lines l_1
             JOIN scm.journal_entries j ON ((j.id = l_1.journal_entry_id)))
          WHERE ((j.posted = true) AND (j.reversed = false) AND (j.reversed_by_je IS NULL))) l ON (((l.account_code = a.account_code) AND (l.company_id = a.company_id))))
  GROUP BY a.account_code, a.account_name, a.account_type, a.company_id
  ORDER BY a.account_code;

create view scm."v_ap_aging" as
 SELECT p.id AS invoice_id,
    p.invoice_number,
    p.supplier_invoice_ref,
    p.supplier_id,
    sup.code AS supplier_code,
    sup.name AS supplier_name,
    p.invoice_date,
    p.due_date,
    p.total_sen,
    p.paid_sen,
    (p.total_sen - p.paid_sen) AS outstanding_sen,
        CASE
            WHEN ((p.due_date IS NULL) OR (p.due_date >= CURRENT_DATE)) THEN 0
            ELSE (CURRENT_DATE - p.due_date)
        END AS days_overdue,
        CASE
            WHEN ((p.due_date IS NULL) OR (p.due_date >= CURRENT_DATE)) THEN 'CURRENT'::text
            WHEN (((CURRENT_DATE - p.due_date) >= 1) AND ((CURRENT_DATE - p.due_date) <= 30)) THEN '1-30'::text
            WHEN (((CURRENT_DATE - p.due_date) >= 31) AND ((CURRENT_DATE - p.due_date) <= 60)) THEN '31-60'::text
            WHEN (((CURRENT_DATE - p.due_date) >= 61) AND ((CURRENT_DATE - p.due_date) <= 90)) THEN '61-90'::text
            ELSE '90+'::text
        END AS aging_bucket,
    (p.status)::text AS status,
    p.company_id,
    'PI'::text AS kind
   FROM (scm.purchase_invoices p
     LEFT JOIN scm.suppliers sup ON ((sup.id = p.supplier_id)))
  WHERE ((p.total_sen > p.paid_sen) AND (p.status <> ALL (ARRAY['CANCELLED'::scm.purchase_invoice_status, 'VOID'::scm.purchase_invoice_status])))
UNION ALL
 SELECT a.id AS invoice_id,
    a.invoice_number,
    a.supplier_invoice_ref,
    a.supplier_id,
    sup.code AS supplier_code,
    sup.name AS supplier_name,
    a.invoice_date,
    a.due_date,
    a.total_sen,
    a.paid_sen,
    (a.total_sen - a.paid_sen) AS outstanding_sen,
        CASE
            WHEN ((a.due_date IS NULL) OR (a.due_date >= CURRENT_DATE)) THEN 0
            ELSE (CURRENT_DATE - a.due_date)
        END AS days_overdue,
        CASE
            WHEN ((a.due_date IS NULL) OR (a.due_date >= CURRENT_DATE)) THEN 'CURRENT'::text
            WHEN (((CURRENT_DATE - a.due_date) >= 1) AND ((CURRENT_DATE - a.due_date) <= 30)) THEN '1-30'::text
            WHEN (((CURRENT_DATE - a.due_date) >= 31) AND ((CURRENT_DATE - a.due_date) <= 60)) THEN '31-60'::text
            WHEN (((CURRENT_DATE - a.due_date) >= 61) AND ((CURRENT_DATE - a.due_date) <= 90)) THEN '61-90'::text
            ELSE '90+'::text
        END AS aging_bucket,
    a.status,
    a.company_id,
    'API'::text AS kind
   FROM (scm.ap_invoices a
     LEFT JOIN scm.suppliers sup ON ((sup.id = a.supplier_id)))
  WHERE ((a.total_sen > a.paid_sen) AND (a.status <> ALL (ARRAY['DRAFT'::text, 'CANCELLED'::text])));

create view scm."v_ar_aging" as
 SELECT id AS invoice_id,
    invoice_number,
    debtor_code,
    debtor_name,
    invoice_date,
    due_date,
    total_sen,
    paid_sen,
    (total_sen - paid_sen) AS outstanding_sen,
        CASE
            WHEN ((due_date IS NULL) OR (due_date >= CURRENT_DATE)) THEN 0
            ELSE (CURRENT_DATE - due_date)
        END AS days_overdue,
        CASE
            WHEN ((due_date IS NULL) OR (due_date >= CURRENT_DATE)) THEN 'CURRENT'::text
            WHEN (((CURRENT_DATE - due_date) >= 1) AND ((CURRENT_DATE - due_date) <= 30)) THEN '1-30'::text
            WHEN (((CURRENT_DATE - due_date) >= 31) AND ((CURRENT_DATE - due_date) <= 60)) THEN '31-60'::text
            WHEN (((CURRENT_DATE - due_date) >= 61) AND ((CURRENT_DATE - due_date) <= 90)) THEN '61-90'::text
            ELSE '90+'::text
        END AS aging_bucket,
    status,
    company_id
   FROM scm.sales_invoices s
  WHERE ((total_sen > paid_sen) AND (status <> ALL (ARRAY['CANCELLED'::scm.sales_invoice_status, 'VOID'::scm.sales_invoice_status])));

create view scm."v_cogs_entries" as
 SELECT c.id,
    c.consumed_at,
    c.warehouse_id,
    w.code AS warehouse_code,
    c.item_code,
    c.variant_key,
    c.qty_consumed,
    c.unit_cost_sen,
    c.total_cost_sen,
    c.source_doc_type,
    c.source_doc_no,
    l.received_at AS lot_received_at,
    l.source_doc_no AS lot_source_doc_no,
    c.company_id
   FROM ((scm.inventory_lot_consumptions c
     JOIN scm.inventory_lots l ON ((l.id = c.lot_id)))
     LEFT JOIN scm.warehouses w ON ((w.id = c.warehouse_id)))
  ORDER BY c.consumed_at DESC;

create view scm."v_customer_credit_balances" as
 SELECT debtor_code,
    max(debtor_name) AS debtor_name,
    sum(amount_sen) AS balance_sen,
    count(*) AS entry_count,
    max(created_at) AS last_entry_at
   FROM scm.customer_credits
  GROUP BY debtor_code;

create view scm."v_do_outstanding" as
 SELECT id,
    do_number,
    so_doc_no,
    debtor_code,
    debtor_name,
    do_date,
    status,
        CASE
            WHEN (status = ANY (ARRAY['INVOICED'::scm.do_status, 'CANCELLED'::scm.do_status])) THEN false
            ELSE true
        END AS is_outstanding,
    company_id
   FROM scm.delivery_orders d;

create view scm."v_gl_entries" as
 SELECT l.id AS line_id,
    j.je_no,
    j.entry_date,
    j.source_type,
    j.source_doc_no,
    l.line_no,
    l.account_code,
    a.account_name,
    a.account_type,
    l.debit_sen,
    l.credit_sen,
    l.party_type,
    l.party_code,
    l.party_name,
    l.notes,
    j.posted,
    j.posted_at,
    j.company_id,
    j.reversed,
    j.reversed_by_je
   FROM ((scm.journal_entry_lines l
     JOIN scm.journal_entries j ON ((j.id = l.journal_entry_id)))
     JOIN scm.accounts a ON (((a.account_code = l.account_code) AND (a.company_id = j.company_id))))
  WHERE (j.posted = true)
  ORDER BY j.entry_date DESC, j.je_no DESC, l.line_no;

create view scm."v_grn_outstanding" as
 SELECT id,
    grn_number,
    supplier_id,
    received_at,
    status,
    created_at,
        CASE
            WHEN (status = 'CANCELLED'::scm.grn_status) THEN false
            WHEN (EXISTS ( SELECT 1
               FROM scm.grn_items gi
              WHERE ((gi.grn_id = g.id) AND (((COALESCE(gi.qty_accepted, 0) - COALESCE(gi.invoiced_qty, 0)) - COALESCE(gi.returned_qty, 0)) > 0)))) THEN true
            ELSE false
        END AS is_outstanding,
    company_id
   FROM scm.grns g;

create view scm."v_inventory_all_skus" as
 SELECT p.code AS item_code,
    p.name AS product_name,
    p.category,
    p.size_label,
    w.id AS warehouse_id,
    w.code AS warehouse_code,
    w.name AS warehouse_name,
    COALESCE(b.qty, (0)::numeric) AS qty,
    b.last_movement_at,
    COALESCE(v.value_sen, (0)::bigint) AS value_sen,
    ms.supplier_code AS main_supplier_code,
    ms.supplier_name AS main_supplier_name,
    ms.unit_price_sen AS main_supplier_price_sen,
    w.company_id
   FROM ((((scm.mfg_products p
     CROSS JOIN scm.warehouses w)
     LEFT JOIN ( SELECT inventory_balances.warehouse_id,
            inventory_balances.item_code,
            sum(inventory_balances.qty) AS qty,
            max(inventory_balances.last_movement_at) AS last_movement_at
           FROM scm.inventory_balances
          GROUP BY inventory_balances.warehouse_id, inventory_balances.item_code) b ON (((b.warehouse_id = w.id) AND (b.item_code = p.code))))
     LEFT JOIN ( SELECT inventory_lots.warehouse_id,
            inventory_lots.item_code,
            sum((inventory_lots.qty_remaining * inventory_lots.unit_cost_sen)) AS value_sen
           FROM scm.inventory_lots
          WHERE (inventory_lots.qty_remaining > 0)
          GROUP BY inventory_lots.warehouse_id, inventory_lots.item_code) v ON (((v.warehouse_id = w.id) AND (v.item_code = p.code))))
     LEFT JOIN LATERAL ( SELECT sup.code AS supplier_code,
            sup.name AS supplier_name,
            smb.unit_price_sen
           FROM (scm.supplier_material_bindings smb
             JOIN scm.suppliers sup ON ((sup.id = smb.supplier_id)))
          WHERE (smb.item_code = p.code)
          ORDER BY smb.is_main_supplier DESC, smb.unit_price_sen
         LIMIT 1) ms ON (true))
  WHERE ((w.is_active = true) AND (p.status = 'ACTIVE'::scm.mfg_product_status) AND (p.company_id = w.company_id));

create view scm."v_inventory_lots_open" as
 SELECT l.id,
    l.warehouse_id,
    w.code AS warehouse_code,
    l.item_code,
    l.variant_key,
    l.product_name,
    l.qty_received,
    l.qty_remaining,
    l.unit_cost_sen,
    (l.qty_remaining * l.unit_cost_sen) AS remaining_value_sen,
    l.received_at,
    l.source_doc_type,
    l.source_doc_no,
    l.batch_no,
    l.company_id
   FROM (scm.inventory_lots l
     LEFT JOIN scm.warehouses w ON ((w.id = l.warehouse_id)))
  WHERE (l.qty_remaining > 0)
  ORDER BY l.received_at;

create view scm."v_inventory_product_totals" as
 SELECT p.code AS item_code,
    p.name AS product_name,
    p.category,
    p.size_label,
    p.base_price_sen,
    p.price1_sen,
    p.branding,
    COALESCE(b.qty, (0)::numeric) AS total_qty,
    COALESCE(v.value_sen, (0)::bigint) AS total_value_sen,
    b.last_movement_at,
    ms.supplier_code AS main_supplier_code,
    ms.supplier_name AS main_supplier_name,
    ms.unit_price_sen AS main_supplier_price_sen,
    p.company_id
   FROM (((scm.mfg_products p
     LEFT JOIN ( SELECT inventory_balances.item_code,
            inventory_balances.company_id,
            sum(inventory_balances.qty) AS qty,
            max(inventory_balances.last_movement_at) AS last_movement_at
           FROM scm.inventory_balances
          GROUP BY inventory_balances.item_code, inventory_balances.company_id) b ON (((b.item_code = p.code) AND (b.company_id = p.company_id))))
     LEFT JOIN ( SELECT inventory_lots.item_code,
            inventory_lots.company_id,
            sum((inventory_lots.qty_remaining * inventory_lots.unit_cost_sen)) AS value_sen
           FROM scm.inventory_lots
          WHERE (inventory_lots.qty_remaining > 0)
          GROUP BY inventory_lots.item_code, inventory_lots.company_id) v ON (((v.item_code = p.code) AND (v.company_id = p.company_id))))
     LEFT JOIN LATERAL ( SELECT sup.code AS supplier_code,
            sup.name AS supplier_name,
            smb.unit_price_sen
           FROM (scm.supplier_material_bindings smb
             JOIN scm.suppliers sup ON ((sup.id = smb.supplier_id)))
          WHERE (smb.item_code = p.code)
          ORDER BY smb.is_main_supplier DESC, smb.unit_price_sen
         LIMIT 1) ms ON (true))
  WHERE (p.status = 'ACTIVE'::scm.mfg_product_status);

create view scm."v_inventory_value" as
 SELECT l.warehouse_id,
    w.code AS warehouse_code,
    l.item_code,
    l.variant_key,
    l.product_name,
    sum(l.qty_remaining) AS qty_on_hand,
    sum((l.qty_remaining * l.unit_cost_sen)) AS value_sen,
        CASE
            WHEN (sum(l.qty_remaining) > 0) THEN (sum((l.qty_remaining * l.unit_cost_sen)) / sum(l.qty_remaining))
            ELSE (0)::bigint
        END AS avg_unit_cost_sen,
    l.company_id
   FROM (scm.inventory_lots l
     LEFT JOIN scm.warehouses w ON ((w.id = l.warehouse_id)))
  WHERE (l.qty_remaining > 0)
  GROUP BY l.warehouse_id, w.code, l.item_code, l.variant_key, l.product_name, l.company_id;

create view scm."v_pi_outstanding" as
 SELECT id,
    invoice_number,
    supplier_invoice_ref,
    supplier_id,
    invoice_date,
    due_date,
    total_sen,
    paid_sen,
    (total_sen - paid_sen) AS outstanding_sen,
    status,
        CASE
            WHEN (status = ANY (ARRAY['PAID'::scm.purchase_invoice_status, 'CANCELLED'::scm.purchase_invoice_status])) THEN false
            WHEN (total_sen > paid_sen) THEN true
            ELSE false
        END AS is_outstanding,
    company_id
   FROM scm.purchase_invoices pi;

create view scm."v_po_outstanding" as
 SELECT po.id,
    po.po_number,
    po.supplier_id,
    po.po_date,
    po.expected_at,
    po.currency,
    po.subtotal_sen,
    po.total_sen,
    po.status,
    COALESCE(sum(poi.qty), (0)::bigint) AS qty_ordered,
    COALESCE(sum(poi.received_qty), (0)::bigint) AS qty_received,
    (COALESCE(sum(poi.qty), (0)::bigint) - COALESCE(sum(poi.received_qty), (0)::bigint)) AS qty_outstanding,
        CASE
            WHEN (po.status = ANY (ARRAY['RECEIVED'::scm.po_status, 'CANCELLED'::scm.po_status])) THEN false
            WHEN (COALESCE(sum(poi.qty), (0)::bigint) > COALESCE(sum(poi.received_qty), (0)::bigint)) THEN true
            ELSE false
        END AS is_outstanding,
    po.company_id
   FROM (scm.purchase_orders po
     LEFT JOIN scm.purchase_order_items poi ON ((poi.purchase_order_id = po.id)))
  GROUP BY po.id;

create view scm."v_po_outstanding_lines" as
 SELECT poi.id AS po_item_id,
    po.id AS po_id,
    po.po_number,
    po.linked_ac_docno AS ac_po_no,
    po.po_date,
    po.status,
    po.supplier_id,
    s.code AS creditor_code,
    s.name AS creditor_name,
    soi.doc_no AS so_doc_no,
    poi.item_code,
    poi.material_name AS item_desc,
    poi.description2 AS item_desc2,
    poi.item_group,
    poi.warehouse_id,
    w.code AS location_code,
    w.name AS location_name,
    poi.qty,
    poi.received_qty,
    (poi.qty - COALESCE(poi.received_qty, 0)) AS remaining_qty,
    poi.delivery_date,
    poi.supplier_delivery_date_2,
    poi.supplier_delivery_date_3,
    poi.line_no,
    poi.so_item_id,
        CASE
            WHEN (po.status = ANY (ARRAY['RECEIVED'::scm.po_status, 'CANCELLED'::scm.po_status])) THEN false
            WHEN ((poi.qty - COALESCE(poi.received_qty, 0)) > 0) THEN true
            ELSE false
        END AS is_outstanding,
    po.company_id
   FROM ((((scm.purchase_orders po
     JOIN scm.purchase_order_items poi ON ((poi.purchase_order_id = po.id)))
     LEFT JOIN scm.suppliers s ON ((s.id = po.supplier_id)))
     LEFT JOIN scm.warehouses w ON ((w.id = poi.warehouse_id)))
     LEFT JOIN scm.mfg_sales_order_items soi ON ((soi.id = poi.so_item_id)));

create view scm."v_pr_outstanding" as
 SELECT id,
    return_number,
    supplier_id,
    return_date,
    status,
    refund_sen,
        CASE
            WHEN (status = ANY (ARRAY['COMPLETED'::scm.purchase_return_status, 'CANCELLED'::scm.purchase_return_status])) THEN false
            ELSE true
        END AS is_outstanding,
    company_id
   FROM scm.purchase_returns pr;

create view scm."v_si_outstanding" as
 SELECT id,
    invoice_number,
    so_doc_no,
    delivery_order_id,
    debtor_code,
    debtor_name,
    invoice_date,
    due_date,
    total_sen,
    paid_sen,
    (total_sen - paid_sen) AS outstanding_sen,
    status,
        CASE
            WHEN (status = ANY (ARRAY['PAID'::scm.sales_invoice_status, 'CANCELLED'::scm.sales_invoice_status])) THEN false
            WHEN (total_sen > paid_sen) THEN true
            ELSE false
        END AS is_outstanding,
    company_id
   FROM scm.sales_invoices s;

create view scm."v_so_outstanding" as
 SELECT doc_no,
    so_date,
    debtor_code,
    debtor_name,
    status,
    local_total_sen,
    total_revenue_sen,
        CASE
            WHEN (status = ANY (ARRAY['DELIVERED'::scm.mfg_so_status, 'INVOICED'::scm.mfg_so_status, 'CLOSED'::scm.mfg_so_status, 'CANCELLED'::scm.mfg_so_status])) THEN false
            ELSE true
        END AS is_outstanding,
    company_id
   FROM scm.mfg_sales_orders so;

create materialized view scm."mv_ar_aging" as
 SELECT COALESCE(v_po_outstanding.company_id, (0)::bigint) AS company_id,
    'po'::text AS module,
    count(*) AS cnt,
    COALESCE(sum(v_po_outstanding.total_sen), (0)::bigint) AS total_sen,
    (0)::bigint AS total_outstanding_sen
   FROM scm.v_po_outstanding
  WHERE v_po_outstanding.is_outstanding
  GROUP BY COALESCE(v_po_outstanding.company_id, (0)::bigint)
UNION ALL
 SELECT COALESCE(v_grn_outstanding.company_id, (0)::bigint) AS company_id,
    'grn'::text AS module,
    count(*) AS cnt,
    (0)::bigint AS total_sen,
    (0)::bigint AS total_outstanding_sen
   FROM scm.v_grn_outstanding
  WHERE v_grn_outstanding.is_outstanding
  GROUP BY COALESCE(v_grn_outstanding.company_id, (0)::bigint)
UNION ALL
 SELECT COALESCE(v_pi_outstanding.company_id, (0)::bigint) AS company_id,
    'pi'::text AS module,
    count(*) AS cnt,
    COALESCE(sum(v_pi_outstanding.total_sen), (0)::bigint) AS total_sen,
    COALESCE(sum(v_pi_outstanding.outstanding_sen), (0)::bigint) AS total_outstanding_sen
   FROM scm.v_pi_outstanding
  WHERE v_pi_outstanding.is_outstanding
  GROUP BY COALESCE(v_pi_outstanding.company_id, (0)::bigint)
UNION ALL
 SELECT COALESCE(v_pr_outstanding.company_id, (0)::bigint) AS company_id,
    'pr'::text AS module,
    count(*) AS cnt,
    (0)::bigint AS total_sen,
    (0)::bigint AS total_outstanding_sen
   FROM scm.v_pr_outstanding
  WHERE v_pr_outstanding.is_outstanding
  GROUP BY COALESCE(v_pr_outstanding.company_id, (0)::bigint)
UNION ALL
 SELECT COALESCE(v_so_outstanding.company_id, (0)::bigint) AS company_id,
    'so'::text AS module,
    count(*) AS cnt,
    COALESCE(sum(v_so_outstanding.local_total_sen), (0)::bigint) AS total_sen,
    (0)::bigint AS total_outstanding_sen
   FROM scm.v_so_outstanding
  WHERE v_so_outstanding.is_outstanding
  GROUP BY COALESCE(v_so_outstanding.company_id, (0)::bigint)
UNION ALL
 SELECT COALESCE(v_do_outstanding.company_id, (0)::bigint) AS company_id,
    'do'::text AS module,
    count(*) AS cnt,
    (0)::bigint AS total_sen,
    (0)::bigint AS total_outstanding_sen
   FROM scm.v_do_outstanding
  WHERE v_do_outstanding.is_outstanding
  GROUP BY COALESCE(v_do_outstanding.company_id, (0)::bigint)
UNION ALL
 SELECT COALESCE(v_si_outstanding.company_id, (0)::bigint) AS company_id,
    'si'::text AS module,
    count(*) AS cnt,
    COALESCE(sum(v_si_outstanding.total_sen), (0)::bigint) AS total_sen,
    COALESCE(sum(v_si_outstanding.outstanding_sen), (0)::bigint) AS total_outstanding_sen
   FROM scm.v_si_outstanding
  WHERE (v_si_outstanding.is_outstanding AND (v_si_outstanding.status <> 'DRAFT'::scm.sales_invoice_status))
  GROUP BY COALESCE(v_si_outstanding.company_id, (0)::bigint);

CREATE UNIQUE INDEX mv_ar_aging_company_module_uidx ON scm.mv_ar_aging USING btree (company_id, module);
CREATE OR REPLACE FUNCTION scm.so_has_open_amendment(so scm.mfg_sales_orders_with_payment_totals)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT EXISTS (
    SELECT 1
      FROM scm.so_amendments a
     WHERE a.so_doc_no = so.doc_no
       AND a.company_id = so.company_id
       AND a.status NOT IN ('SENT', 'REJECTED')
       AND (a.lane IS NULL OR a.status = 'REQUESTED')
  )
$function$;

CREATE OR REPLACE FUNCTION scm.so_line_categories(so scm.mfg_sales_orders_with_payment_totals)
 RETURNS text[]
 LANGUAGE sql
 STABLE
AS $function$
  SELECT COALESCE(array_agg(DISTINCT
           CASE
             WHEN upper(btrim(coalesce(i.item_group, ''))) LIKE '%BEDFRAME%' THEN 'BEDFRAME'
             WHEN upper(btrim(coalesce(i.item_group, ''))) LIKE '%SOFA%'     THEN 'SOFA'
             WHEN upper(btrim(coalesce(i.item_group, ''))) LIKE '%MATTRESS%' THEN 'MATTRESS'
             WHEN upper(btrim(coalesce(i.item_group, ''))) LIKE '%ACCESSOR%' THEN 'ACCESSORY'
             WHEN upper(btrim(coalesce(i.item_group, ''))) LIKE '%SERVICE%'  THEN 'SERVICE'
             ELSE 'OTHERS'
           END), '{}'::text[])
    FROM scm.mfg_sales_order_items i
   WHERE i.doc_no = so.doc_no
     AND i.company_id = so.company_id
     AND i.cancelled = false
$function$;

CREATE OR REPLACE FUNCTION scm.so_line_warehouse_ids(so scm.mfg_sales_orders_with_payment_totals)
 RETURNS uuid[]
 LANGUAGE sql
 STABLE
AS $function$
  SELECT COALESCE(array_agg(DISTINCT i.warehouse_id) FILTER (WHERE i.warehouse_id IS NOT NULL), '{}'::uuid[])
    FROM scm.mfg_sales_order_items i
   WHERE i.doc_no = so.doc_no
     AND i.company_id = so.company_id
     AND i.cancelled = false
$function$;


CREATE CONSTRAINT TRIGGER trg_do_line_integrity_lock AFTER DELETE OR UPDATE OF delivery_order_id ON scm.delivery_order_items DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION scm.fn_do_line_integrity_lock();
CREATE TRIGGER trg_do_header_delete_lock BEFORE DELETE ON scm.delivery_orders FOR EACH ROW EXECUTE FUNCTION scm.fn_do_header_delete_lock();
CREATE TRIGGER vp_catalogue_changed AFTER INSERT OR DELETE ON scm.fabric_trackings FOR EACH STATEMENT EXECUTE FUNCTION scm.vp_catalogue_mark_changed();
CREATE TRIGGER vp_catalogue_changed_upd AFTER UPDATE OF company_id, fabric_code, fabric_description, fabric_category, series, price_tier, sofa_price_tier, bedframe_price_tier, is_active ON scm.fabric_trackings FOR EACH STATEMENT EXECUTE FUNCTION scm.vp_catalogue_mark_changed();
CREATE TRIGGER trg_inventory_movement_fifo AFTER INSERT ON scm.inventory_movements FOR EACH ROW EXECUTE FUNCTION scm.fn_inventory_movement_fifo();
CREATE TRIGGER trg_je_balanced BEFORE UPDATE ON scm.journal_entries FOR EACH ROW EXECUTE FUNCTION scm.fn_check_je_balanced();
CREATE TRIGGER vp_catalogue_changed AFTER INSERT OR DELETE ON scm.maintenance_config_history FOR EACH STATEMENT EXECUTE FUNCTION scm.vp_catalogue_mark_changed();
CREATE TRIGGER vp_catalogue_changed_upd AFTER UPDATE OF company_id, scope, config, effective_from ON scm.maintenance_config_history FOR EACH STATEMENT EXECUTE FUNCTION scm.vp_catalogue_mark_changed();
