do $$ declare t text; begin
  for t in select tablename from pg_tables where schemaname = 'scm' loop
    execute format('alter table scm.%I enable row level security', t);
  end loop;
end $$;
grant usage on schema scm to pos_app, service_role;
grant all on all tables in schema scm to pos_app, service_role;
grant usage, select, update on all sequences in schema scm to pos_app, service_role;
grant execute on all functions in schema scm to pos_app, service_role;
